(307602,34178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Narancssárga ... hord fehér inggel.'::text,'nadrágot'::text,'nadrágot'::text,'nadrágot'::text,'Narancssárga nadrágot hord fehér inggel.'::text),
(307614,34180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er trägt in jeder Einstellung ... orange Hose!'::text,'jene'::text,'jene'::text,'diese'::text,'Katastrophe! Er trägt in jeder Einstellung jene orange Hose!'::text),
(307618,34180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він у кожному кадрі в ... помаранчевих штанах!'::text,'тих'::text,'тих'::text,'цих'::text,'Катастрофа! Він у кожному кадрі в тих помаранчевих штанах!'::text),
(307617,34180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Lleva ... pantalones naranjas en cada plano!'::text,'esos'::text,'ese'::text,'este'::text,'¡Desastre! ¡Lleva esos pantalones naranjas en cada plano!'::text),
(307616,34180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il porte ... pantalon orange dans chaque plan !'::text,'ce'::text,'ce'::text,'ce'::text,'Catastrophe ! Il porte ce pantalon orange dans chaque plan !'::text),
(307619,34180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Her çekimde ... turuncu pantolonu giyiyor!'::text,'şu'::text,'şu'::text,'bu'::text,'Felaket! Her çekimde şu turuncu pantolonu giyiyor!'::text),
(307620,34180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Minden snittben ... a narancssárga nadrágot hordja!'::text,'azt'::text,'azt'::text,'ezt'::text,'Katasztrófa! Minden snittben azt a narancssárga nadrágot hordja!'::text),
(307623,34181,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Er trägt die orange Hose in ... Einstellungen hintereinander!'::text,'zwei'::text,'zweiten'::text,'zweimal'::text,'Unglaublich! Er trägt die orange Hose in zwei Einstellungen hintereinander!'::text),
(307627,34181,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Він у помаранчевих штанах у ... кадрах поспіль!'::text,'двох'::text,'других'::text,'двічі'::text,'Неймовірно! Він у помаранчевих штанах у двох кадрах поспіль!'::text),
(307626,34181,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡Lleva pantalones naranjas en ... planos seguidos!'::text,'dos'::text,'segundos'::text,'dos veces'::text,'¡Increíble! ¡Lleva pantalones naranjas en dos planos seguidos!'::text),
(307625,34181,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Il porte un pantalon orange dans ... plans d''affilée !'::text,'deux'::text,'deuxièmes'::text,'deux fois'::text,'Incroyable ! Il porte un pantalon orange dans deux plans d''affilée !'::text),
(307628,34181,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Arka arkaya ... çekimde turuncu pantolon giyiyor!'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'İnanılmaz! Arka arkaya iki çekimde turuncu pantolon giyiyor!'::text),
(307629,34181,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! ... egymást követő snittben narancssárga nadrágot hord!'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Hihetetlen! Két egymást követő snittben narancssárga nadrágot hord!'::text),
(307632,34182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat sie nicht mehr viel orange ... zum Anziehen.'::text,'Kleidung'::text,'Kleidung'::text,'Kleider'::text,'Hör zu, angeblich hat sie nicht mehr viel orange Kleidung zum Anziehen.'::text),
(307636,34182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, у неї лишилося небагато помаранчевого ..., щоб носити.'::text,'одягу'::text,'одягу'::text,'суконь'::text,'Слухай, кажуть, у неї лишилося небагато помаранчевого одягу, щоб носити.'::text),
(307635,34182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer no le queda mucha ... naranja para ponerse.'::text,'ropa'::text,'ropa'::text,'vestidos'::text,'Oye, al parecer no le queda mucha ropa naranja para ponerse.'::text),
(307634,34182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment, il ne lui reste plus beaucoup de ... orange à porter.'::text,'vêtements'::text,'vêtements'::text,'robes'::text,'Écoute, apparemment, il ne lui reste plus beaucoup de vêtements orange à porter.'::text),
(307637,34182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, galiba giyecek pek turuncu ... kalmamış.'::text,'kıyafeti'::text,'kıyafetleri'::text,'elbiseleri'::text,'Dinle, galiba giyecek pek turuncu kıyafeti kalmamış.'::text),
(307638,34182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag nem sok narancssárga ... maradt, amit felvehetne.'::text,'ruhaneműje'::text,'ruhaneműje'::text,'ruhája'::text,'Figyelj, állítólag nem sok narancssárga ruhaneműje maradt, amit felvehetne.'::text),
(307650,34184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, angeblich ... in zwei seiner Looks orange Hosen dabei.'::text,'sind'::text,'ist'::text,'sein'::text,'Also, angeblich sind in zwei seiner Looks orange Hosen dabei.'::text),
(307654,34184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, у двох його образах ... помаранчеві штани.'::text,'є'::text,'є'::text,'бути'::text,'Коротше, кажуть, у двох його образах є помаранчеві штани.'::text),
(307653,34184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer ... pantalones naranjas en dos de sus looks.'::text,'hay'::text,'hay'::text,'hay'::text,'Vale, al parecer hay pantalones naranjas en dos de sus looks.'::text),
(307652,34184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, ... des pantalons orange dans deux de ses looks.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Bon, apparemment, il y a des pantalons orange dans deux de ses looks.'::text),
(307655,34184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani galiba iki kombininde turuncu pantolon ...'::text,'var'::text,'var'::text,'olmak'::text,'Yani galiba iki kombininde turuncu pantolon var.'::text),
(307656,34184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag két szettjében is narancssárga nadrágok ...'::text,'vannak'::text,'van'::text,'lenni'::text,'Szóval állítólag két szettjében is narancssárga nadrágok vannak.'::text),
(327270,36364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ... sie ein weißes Kleid mit weißen High Heels.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Jetzt trägt sie ein weißes Kleid mit weißen High Heels.'::text),
(327274,36364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... білу сукню з білими підборами.'::text,'носить'::text,'носить'::text,'носить'::text,'Зараз вона носить білу сукню з білими підборами.'::text),
(327273,36364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ella ... un vestido blanco con tacones blancos.'::text,'lleva puesto'::text,'lleva'::text,'lleva puesto'::text,'Ahora ella lleva puesto un vestido blanco con tacones blancos.'::text),
(327272,36364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant, elle ... une robe blanche avec des talons blancs.'::text,'porte'::text,'porte'::text,'porte'::text,'Maintenant, elle porte une robe blanche avec des talons blancs.'::text),
(327275,36364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi beyaz topuklularla beyaz bir elbise ...'::text,'giyiyor'::text,'giyer'::text,'giyiyor'::text,'Şimdi beyaz topuklularla beyaz bir elbise giyiyor.'::text),
(327276,36364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most egy fehér ruhát ... fehér magassarkúval.'::text,'visel'::text,'visel'::text,'visel'::text,'Most egy fehér ruhát visel fehér magassarkúval.'::text),
(327279,36365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trägt sonst Rot, aber jetzt ... sie Weiß.'::text,'trägt'::text,'trägt'::text,NULL::text,'Sie trägt sonst Rot, aber jetzt trägt sie Weiß.'::text),
(327283,36365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона носить червоне, але зараз вона ... біле.'::text,'носить'::text,'носить'::text,NULL::text,'Зазвичай вона носить червоне, але зараз вона носить біле.'::text),
(327282,36365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente viste de rojo, pero ahora ella ... de blanco.'::text,'está vestida'::text,'viste'::text,NULL::text,'Normalmente viste de rojo, pero ahora ella está vestida de blanco.'::text),
(327281,36365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle porte du rouge, mais maintenant elle ... du blanc.'::text,'porte'::text,'porte'::text,NULL::text,'D''habitude, elle porte du rouge, mais maintenant elle porte du blanc.'::text),
(327284,36365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde kırmızı giyer ama şimdi beyaz ...'::text,'giyiyor'::text,'giyer'::text,NULL::text,'Genelde kırmızı giyer ama şimdi beyaz giyiyor.'::text),
(327285,36365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában pirosat hord, de most fehéret ...'::text,'hord'::text,'hord'::text,NULL::text,'Általában pirosat hord, de most fehéret hord.'::text),
(327288,36366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Kaffee, und dieses weiße Kleid ... für immer ruiniert sein!'::text,'wird'::text,'ist'::text,NULL::text,'Ein Kaffee, und dieses weiße Kleid wird für immer ruiniert sein!'::text),
(327292,36366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна кава — і ця біла сукня ... зіпсована назавжди!'::text,'буде'::text,'є'::text,NULL::text,'Одна кава — і ця біла сукня буде зіпсована назавжди!'::text),
(327291,36366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Un café y este vestido blanco ... arruinado para siempre!'::text,'quedará'::text,'está'::text,NULL::text,'¡Un café y este vestido blanco quedará arruinado para siempre!'::text),
(327290,36366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un café, et cette robe blanche ... fichue pour toujours !'::text,'sera'::text,'est'::text,NULL::text,'Un café, et cette robe blanche sera fichue pour toujours !'::text),
(327293,36366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kahve ve bu beyaz elbise sonsuza dek ...!'::text,'mahvolacak'::text,NULL::text,NULL::text,'Bir kahve ve bu beyaz elbise sonsuza dek mahvolacak!'::text),
(327294,36366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kávé, és ez a fehér ruha örökre ... tönkretéve!'::text,'lesz'::text,'van'::text,NULL::text,'Egy kávé, és ez a fehér ruha örökre lesz tönkretéve!'::text),
(327297,36367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie meinte, ihr Plan ist einfach: Sie ... nur noch Weiß tragen.'::text,'wird'::text,'wird'::text,'wird'::text,'Also, sie meinte, ihr Plan ist einfach: Sie wird nur noch Weiß tragen.'::text),
(327301,36367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала, що план простий: вона ... носити тільки біле.'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Коротше, вона сказала, що план простий: вона збирається носити тільки біле.'::text),
(327300,36367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, dijo que su plan es sencillo: ella ... llevar solo blanco.'::text,'va a'::text,'va a'::text,'va a'::text,'Vale, dijo que su plan es sencillo: ella va a llevar solo blanco.'::text),
(327299,36367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle a dit que son plan était simple : elle ... porter seulement du blanc.'::text,'va'::text,'va'::text,'va'::text,'Bon, elle a dit que son plan était simple : elle va porter seulement du blanc.'::text),
(327302,36367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani planının basit olduğunu söyledi: sadece beyaz ...'::text,'giyecek'::text,'giyecek'::text,'giyecek'::text,'Yani planının basit olduğunu söyledi: sadece beyaz giyecek.'::text),
(327303,36367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, egyszerű a terve: csak fehéret ... hordani.'::text,'fog'::text,'fog'::text,'fog'::text,'Szóval azt mondta, egyszerű a terve: csak fehéret fog hordani.'::text),
(327315,36369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, sie hat so viel ... für das weiße Kleid ausgegeben.'::text,'Geld'::text,'Geld'::text,'ein Geld'::text,'Also, ich hab gehört, sie hat so viel Geld für das weiße Kleid ausgegeben.'::text),
(327319,36369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що вона витратила стільки ... на ту білу сукню.'::text,'грошей'::text,'грошей'::text,'грошей'::text,'Коротше, я чула, що вона витратила стільки грошей на ту білу сукню.'::text),
(327318,36369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que se gastó tanto ... en ese vestido blanco.'::text,'dinero'::text,'dinero'::text,'un dinero'::text,'Vale, he oído que se gastó tanto dinero en ese vestido blanco.'::text),
(327317,36369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire qu''elle a dépensé tellement ... pour cette robe blanche.'::text,'d''argent'::text,'d''argent'::text,'d''un argent'::text,'Bon, j''ai entendu dire qu''elle a dépensé tellement d''argent pour cette robe blanche.'::text),
(327320,36369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yani duydum ki o beyaz elbiseye çok fazla ... harcamış.'::text,'para'::text,'paralar'::text,'bir para'::text,'Yani duydum ki o beyaz elbiseye çok fazla para harcamış.'::text),
(327321,36369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval úgy hallottam, annyi ... költött arra a fehér ruhára.'::text,'pénzt'::text,'pénzt'::text,'egy pénzt'::text,'Szóval úgy hallottam, annyi pénzt költött arra a fehér ruhára.'::text),
(327324,36370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du trägst Weiß mit so ... Style.'::text,'viel'::text,'viele'::text,'wenige'::text,'Ehrlich gesagt, du trägst Weiß mit so viel Style.'::text),
(327328,36370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у білому в тебе так ... стилю.'::text,'багато'::text,'багато'::text,'мало'::text,'Чесно, у білому в тебе так багато стилю.'::text),
(327327,36370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, llevas el blanco con ... estilo.'::text,'mucho'::text,'muchos'::text,'pocos'::text,'No te voy a mentir, llevas el blanco con mucho estilo.'::text),
(327326,36370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu portes le blanc avec ... style.'::text,'beaucoup de'::text,'beaucoup de'::text,'peu de'::text,'Franchement, tu portes le blanc avec beaucoup de style.'::text),
(327329,36370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, beyazı o kadar ... tarzla giyiyorsun ki.'::text,'çok'::text,'çok'::text,'az'::text,'Yalan yok, beyazı o kadar çok tarzla giyiyorsun ki.'::text),
(327330,36370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, olyan ... stílussal hordod a fehéret.'::text,'sok'::text,'sok'::text,'kevés'::text,'Nem hazudok, olyan sok stílussal hordod a fehéret.'::text),
(327333,36371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, da ... nichts Cooleres als dein weißes Kleid.'::text,'ist'::text,'sind'::text,'sein'::text,'Ehrlich, da ist nichts Cooleres als dein weißes Kleid.'::text),
(327337,36371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ... нічого крутішого за твою білу сукню.'::text,'немає'::text,'немає'::text,'не бути'::text,'Чесно, немає нічого крутішого за твою білу сукню.'::text),
(327336,36371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... nada más guay que tu vestido blanco.'::text,'no hay'::text,'no hay'::text,'no hay'::text,'Sinceramente, no hay nada más guay que tu vestido blanco.'::text),
(327335,36371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... rien de plus cool que ta robe blanche.'::text,'il n''y a'::text,'il n''y a'::text,'il n''y a'::text,'Franchement, il n''y a rien de plus cool que ta robe blanche.'::text),
(327338,36371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin beyaz elbisenden daha havalı bir şey ...'::text,'yok'::text,'yok'::text,'olmamak'::text,'Açıkçası, senin beyaz elbisenden daha havalı bir şey yok.'::text),
(327339,36371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... semmi menőbb a fehér ruhádnál.'::text,'nincs'::text,'nincsenek'::text,'lenni'::text,'Őszintén, nincs semmi menőbb a fehér ruhádnál.'::text),
(310188,34466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Polizeiauto ... blaue und rote Lichter.'::text,'hat'::text,'haben'::text,'hat'::text,'Das Polizeiauto hat blaue und rote Lichter.'::text),
(310192,34466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поліцейська машина ... сині й червоні вогні.'::text,'має'::text,'мати'::text,'має'::text,'Поліцейська машина має сині й червоні вогні.'::text),
(310191,34466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche de policía ... luces azules y rojas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El coche de policía tiene luces azules y rojas.'::text),
(310190,34466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture de police ... des gyrophares bleus et rouges.'::text,'a'::text,'ont'::text,'a'::text,'La voiture de police a des gyrophares bleus et rouges.'::text),
(310193,34466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polis arabasının mavi ve kırmızı ışıkları ...'::text,'var'::text,'var'::text,'var'::text,'Polis arabasının mavi ve kırmızı ışıkları var.'::text),
(310194,34466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendőrautónak kék és piros villogója ...'::text,'van'::text,'van'::text,'van'::text,'A rendőrautónak kék és piros villogója van.'::text),
(310206,34468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Corgi fährt, und die Polizei folgt in ... weißen Auto.'::text,'ihrem'::text,'ihrem'::text,'unserem'::text,'Der Corgi fährt, und die Polizei folgt in ihrem weißen Auto.'::text),
(310210,34468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коргі кермує, а поліція їде слідом у ... білій машині.'::text,'своїй'::text,'її'::text,'нашій'::text,'Коргі кермує, а поліція їде слідом у своїй білій машині.'::text),
(310209,34468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El corgi conduce y la policía lo sigue en ... coche blanco.'::text,'su'::text,'su'::text,'nuestro'::text,'El corgi conduce y la policía lo sigue en su coche blanco.'::text),
(310208,34468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le corgi conduit, et la police le suit dans ... voiture blanche.'::text,'leur'::text,'sa'::text,'notre'::text,'Le corgi conduit, et la police le suit dans leur voiture blanche.'::text),
(310211,34468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korgi araba sürüyor, polis de ... beyaz arabasıyla peşinden geliyor.'::text,'onların'::text,'onun'::text,'bizim'::text,'Korgi araba sürüyor, polis de onların beyaz arabasıyla peşinden geliyor.'::text),
(310212,34468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A corgi vezet, a rendőrség pedig a fehér ... követi.'::text,'autójukkal'::text,'autójával'::text,'autónkkal'::text,'A corgi vezet, a rendőrség pedig a fehér autójukkal követi.'::text),
(310215,34469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Polizeiauto fährt ... dem Gokart des Corgis.'::text,'hinter'::text,'unter'::text,'in'::text,'Das Polizeiauto fährt hinter dem Gokart des Corgis.'::text),
(310219,34469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поліцейська машина їде ... картом коргі.'::text,'за'::text,'під'::text,'у'::text,'Поліцейська машина їде за картом коргі.'::text),
(310218,34469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche de policía va ... kart del corgi.'::text,'detrás del'::text,'debajo del'::text,'en el'::text,'El coche de policía va detrás del kart del corgi.'::text),
(310217,34469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture de police roule ... kart du corgi.'::text,'derrière le'::text,'sous le'::text,'dans le'::text,'La voiture de police roule derrière le kart du corgi.'::text),
(310220,34469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polis arabası korginin go-kartının ... gidiyor.'::text,'arkasından'::text,'altından'::text,'içinde'::text,'Polis arabası korginin go-kartının arkasından gidiyor.'::text),
(310221,34469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendőrautó a corgi ... halad.'::text,'gokartja mögött'::text,'gokartja alatt'::text,'gokartjában'::text,'A rendőrautó a corgi gokartja mögött halad.'::text),
(310224,34470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Hund fährt, und ein Polizeiauto folgt.'::text,'Ein'::text,'Erster'::text,'Einmal'::text,'Ein Hund fährt, und ein Polizeiauto folgt.'::text),
(310228,34470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... пес кермує, і одна поліцейська машина їде слідом.'::text,'Один'::text,'Перший'::text,'Раз'::text,'Один пес кермує, і одна поліцейська машина їде слідом.'::text),
(310227,34470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... perro conduce y un coche de policía lo sigue.'::text,'Un'::text,'Primer'::text,'Una vez'::text,'Un perro conduce y un coche de policía lo sigue.'::text),
(310226,34470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... chien conduit, et une voiture de police suit.'::text,'Un'::text,'Premier'::text,'Une fois'::text,'Un chien conduit, et une voiture de police suit.'::text),
(310229,34470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... köpek araba sürüyor ve bir polis arabası peşinden geliyor.'::text,'Bir'::text,'Birinci'::text,'Bir kez'::text,'Bir köpek araba sürüyor ve bir polis arabası peşinden geliyor.'::text),
(310230,34470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kutya vezet, és egy rendőrautó követi.'::text,'Egy'::text,'Első'::text,'Egyszer'::text,'Egy kutya vezet, és egy rendőrautó követi.'::text),
(310233,34471,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hier ist nicht viel ..., also hat die Polizei freie Bahn.'::text,'Verkehr'::text,'Verkehr'::text,'Autos'::text,'Bro, hier ist nicht viel Verkehr, also hat die Polizei freie Bahn.'::text),
(310237,34471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, тут небагато ..., тож у поліції вільна дорога.'::text,'руху'::text,'руху'::text,'машин'::text,'Бро, тут небагато руху, тож у поліції вільна дорога.'::text),
(310236,34471,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, aquí no hay mucho ..., así que la poli tiene vía libre.'::text,'tráfico'::text,'tráfico'::text,'coches'::text,'Tío, aquí no hay mucho tráfico, así que la poli tiene vía libre.'::text),
(310235,34471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, y a pas beaucoup de ... ici, donc la police a la voie libre.'::text,'circulation'::text,'circulation'::text,'voitures'::text,'Frère, y a pas beaucoup de circulation ici, donc la police a la voie libre.'::text),
(310238,34471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, burada pek ... yok, polisin önü açık.'::text,'trafik'::text,'trafikler'::text,'arabalar'::text,'Kanka, burada pek trafik yok, polisin önü açık.'::text),
(310239,34471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nincs itt sok ..., szóval a rendőrségnek szabad az út.'::text,'forgalom'::text,'forgalom'::text,'autó'::text,'Tesó, nincs itt sok forgalom, szóval a rendőrségnek szabad az út.'::text),
(310242,34472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Hund hat ... Angst vor der Polizei, echt.'::text,'keine'::text,'etwas'::text,'viele'::text,'Bro, der Hund hat keine Angst vor der Polizei, echt.'::text),
(310246,34472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, пес не має ... страху перед поліцією, чесно.'::text,'жодного'::text,'трохи'::text,'багато'::text,'Бро, пес не має жодного страху перед поліцією, чесно.'::text),
(310245,34472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el perro no tiene ... miedo a la poli, en serio.'::text,'ningún'::text,'algo de'::text,'muchos'::text,'Tío, el perro no tiene ningún miedo a la poli, en serio.'::text),
(310244,34472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le chien n''a ... peur de la police, sérieux.'::text,'aucune'::text,'de la'::text,'beaucoup de'::text,'Frère, le chien n''a aucune peur de la police, sérieux.'::text),
(310247,34472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, köpeğin polisten ... korkusu yok, cidden.'::text,'hiç'::text,'biraz'::text,'çok'::text,'Kanka, köpeğin polisten hiç korkusu yok, cidden.'::text),
(310248,34472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kutyának ... félelme sincs a rendőrségtől, komolyan.'::text,'semmilyen'::text,'némi'::text,'sok'::text,'Tesó, a kutyának semmilyen félelme sincs a rendőrségtől, komolyan.'::text),
(323328,35926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die dicke Echse ... aufs Klo.'::text,'geht'::text,'gehen'::text,'gehend'::text,'Die dicke Echse geht aufs Klo.'::text),
(323332,35926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Товста ящірка ... в туалет.'::text,'іде'::text,'йти'::text,'ідучи'::text,'Товста ящірка іде в туалет.'::text),
(323331,35926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lagarto gordo ... al baño.'::text,'va'::text,'ir'::text,'yendo'::text,'El lagarto gordo va al baño.'::text),
(323330,35926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gros lézard ... aux toilettes.'::text,'va'::text,'aller'::text,'allant'::text,'Le gros lézard va aux toilettes.'::text),
(323333,35926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişko kertenkele tuvalete ...'::text,'gider'::text,'gitmek'::text,'giderek'::text,'Şişko kertenkele tuvalete gider.'::text),
(323334,35926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dagi gyík ... a vécébe.'::text,'megy'::text,'menni'::text,'menő'::text,'A dagi gyík megy a vécébe.'::text),
(323337,35927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! ... die dicke Echse überhaupt durch die Klotür passen?'::text,'Kann'::text,'Ist'::text,'Hat'::text,'Albtraum! Kann die dicke Echse überhaupt durch die Klotür passen?'::text),
(323341,35927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Чи ... товста ящірка взагалі пролізти в двері туалету?'::text,'може'::text,'є'::text,'має'::text,'Жах! Чи може товста ящірка взагалі пролізти в двері туалету?'::text),
(323340,35927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¿... el lagarto gordo siquiera pasar por la puerta del baño?'::text,'Puede'::text,'Está'::text,'Tiene'::text,'¡Pesadilla! ¿Puede el lagarto gordo siquiera pasar por la puerta del baño?'::text),
(323339,35927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Est-ce que le gros lézard ... même passer par la porte des toilettes ?'::text,'peut'::text,'est'::text,'a'::text,'Cauchemar ! Est-ce que le gros lézard peut même passer par la porte des toilettes ?'::text),
(323342,35927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Şişko kertenkele tuvalet kapısından ... mi ki?'::text,'sığabilir'::text,NULL::text,'var'::text,'Kâbus! Şişko kertenkele tuvalet kapısından sığabilir mi ki?'::text),
(323343,35927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! ... egyáltalán a dagi gyík a vécéajtón?'::text,'Átférhet'::text,'Van'::text,'Van'::text,'Rémálom! Átférhet egyáltalán a dagi gyík a vécéajtón?'::text),
(323346,35928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Die Echse verbringt ... auf dem Klo!'::text,'5 Minuten'::text,'5 Minute'::text,'5 Minuten'::text,'Albtraum! Die Echse verbringt 5 Minuten auf dem Klo!'::text),
(323350,35928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Ящірка проводить ... у туалеті!'::text,'5 хвилин'::text,'5 хвилина'::text,'5 хвилин'::text,'Жах! Ящірка проводить 5 хвилин у туалеті!'::text),
(323349,35928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El lagarto se pasa ... en el baño!'::text,'5 minutos'::text,'5 minuto'::text,'5 minutos'::text,'¡Pesadilla! ¡El lagarto se pasa 5 minutos en el baño!'::text),
(323348,35928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le lézard passe ... aux toilettes !'::text,'5 minutes'::text,'5 minute'::text,'5 minutes'::text,'Cauchemar ! Le lézard passe 5 minutes aux toilettes !'::text),
(323351,35928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Kertenkele tuvalette ... geçiriyor!'::text,'5 dakika'::text,'5 dakika'::text,'5 dakikalar'::text,'Kâbus! Kertenkele tuvalette 5 dakika geçiriyor!'::text),
(323352,35928,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A gyík ... tölt a vécében!'::text,'5 percet'::text,'5 percet'::text,'5 percet'::text,'Rémálom! A gyík 5 percet tölt a vécében!'::text),
(323355,35929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine dicke Echse geht aufs Klo, und ... Echse kommt total schlank wieder raus!'::text,'die'::text,'eine'::text,'eine'::text,'Eine dicke Echse geht aufs Klo, und die Echse kommt total schlank wieder raus!'::text),
(323359,35929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Товста ящірка заходить у туалет, а ... ящірка виходить геть струнка!'::text,''::text,NULL::text,NULL::text,'Товста ящірка заходить у туалет, а ящірка виходить геть струнка!'::text),
(323358,35929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Un lagarto gordo entra al baño y ... lagarto sale completamente delgado!'::text,'el'::text,'un'::text,'un'::text,'¡Un lagarto gordo entra al baño y el lagarto sale completamente delgado!'::text),
(323357,35929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un gros lézard entre aux toilettes, et ... lézard en ressort tout mince !'::text,'le'::text,'un'::text,'un'::text,'Un gros lézard entre aux toilettes, et le lézard en ressort tout mince !'::text),
(323360,35929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişko bir kertenkele tuvalete giriyor ve ... kertenkele tamamen incelmiş olarak çıkıyor!'::text,''::text,'bir'::text,'bir'::text,'Şişko bir kertenkele tuvalete giriyor ve kertenkele tamamen incelmiş olarak çıkıyor!'::text),
(323361,35929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy dagi gyík bemegy a vécébe, és ... gyík teljesen karcsún jön ki!'::text,'a'::text,'egy'::text,'egy'::text,'Egy dagi gyík bemegy a vécébe, és a gyík teljesen karcsún jön ki!'::text),
(323364,35930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Klo ist drinnen, also ... die Echse reingehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Klo ist drinnen, also muss die Echse reingehen.'::text),
(323368,35930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туалет усередині, тож ящірка ... йти всередину.'::text,'має'::text,'мусить'::text,'мала б'::text,'Туалет усередині, тож ящірка має йти всередину.'::text),
(323367,35930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El baño está dentro, así que el lagarto ... entrar.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El baño está dentro, así que el lagarto tiene que entrar.'::text),
(323366,35930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les toilettes sont à l''intérieur, donc le lézard ... entrer.'::text,'doit'::text,'doit'::text,'devrait'::text,'Les toilettes sont à l''intérieur, donc le lézard doit entrer.'::text),
(323369,35930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvalet içeride, bu yüzden kertenkele içeri ...'::text,'girmek zorunda'::text,'girmeli'::text,'girmeli'::text,'Tuvalet içeride, bu yüzden kertenkele içeri girmek zorunda.'::text),
(323370,35930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vécé bent van, ezért a gyíknak be ... mennie.'::text,'kell'::text,'kell'::text,'kellene'::text,'A vécé bent van, ezért a gyíknak be kell mennie.'::text),
(323373,35931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kam schlank aus dem Klo, also ... alle Echsen es benutzen.'::text,'sollten'::text,'sollen'::text,'sollten'::text,'Er kam schlank aus dem Klo, also sollten alle Echsen es benutzen.'::text),
(323377,35931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вийшов з туалету струнким, тож усі ящірки ... ним користуватися.'::text,'мали б'::text,'будуть'::text,'мали б'::text,'Він вийшов з туалету струнким, тож усі ящірки мали б ним користуватися.'::text),
(323376,35931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salió del baño delgado, así que todos los lagartos ... usarlo.'::text,'deberían'::text,'deberán'::text,'deberían'::text,'Salió del baño delgado, así que todos los lagartos deberían usarlo.'::text),
(323375,35931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est sorti des toilettes tout mince, donc tous les lézards ... l''utiliser.'::text,'devraient'::text,'devront'::text,'devraient'::text,'Il est sorti des toilettes tout mince, donc tous les lézards devraient l''utiliser.'::text),
(323378,35931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvaletten incelmiş çıktı, bu yüzden bütün kertenkeleler onu ...'::text,'kullanmalı'::text,'kullanacak'::text,'kullanmalı'::text,'Tuvaletten incelmiş çıktı, bu yüzden bütün kertenkeleler onu kullanmalı.'::text),
(323379,35931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karcsún jött ki a vécéből, ezért minden gyíknak ... használnia.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Karcsún jött ki a vécéből, ezért minden gyíknak kellene használnia.'::text),
(315867,35097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann brät ... Eier am Ufer.'::text,'seine'::text,'ihre'::text,'seine'::text,'Der Mann brät seine Eier am Ufer.'::text),
(315871,35097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік смажить ... яйця на березі.'::text,'свої'::text,'свої'::text,'свої'::text,'Чоловік смажить свої яйця на березі.'::text),
(315870,35097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre cocina ... huevos en la orilla.'::text,'sus'::text,'sus'::text,'sus'::text,'El hombre cocina sus huevos en la orilla.'::text),
(315869,35097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme cuisine ... œufs sur la rive.'::text,'ses'::text,'ses'::text,'ses'::text,'L''homme cuisine ses œufs sur la rive.'::text),
(315872,35097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam kıyıda ... yumurtalarını pişiriyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam kıyıda onun yumurtalarını pişiriyor.'::text),
(315873,35097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi a parton megsüti a ...'::text,'tojásait'::text,'tojásait'::text,'tojásait'::text,'A férfi a parton megsüti a tojásait.'::text),
(315876,35098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... isst er am Ufer? Eier und Brot.'::text,'Was'::text,'Wo'::text,'Wer'::text,'Was isst er am Ufer? Eier und Brot.'::text),
(315880,35098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він їсть на березі? Яйця й хліб.'::text,'Що'::text,'Де'::text,'Хто'::text,'Що він їсть на березі? Яйця й хліб.'::text),
(315879,35098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... come en la orilla? Huevos y pan.'::text,'Qué'::text,'Dónde'::text,'Quién'::text,'¿Qué come en la orilla? Huevos y pan.'::text),
(315878,35098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mange-t-il sur la rive ? Des œufs et du pain.'::text,'Que'::text,'Où'::text,'Qui'::text,'Que mange-t-il sur la rive ? Des œufs et du pain.'::text),
(315881,35098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyıda ... yiyor? Yumurta ve ekmek.'::text,'ne'::text,'nerede'::text,'kim'::text,'Kıyıda ne yiyor? Yumurta ve ekmek.'::text),
(315882,35098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eszik a parton? Tojást és kenyeret.'::text,'Mit'::text,'Hol'::text,'Ki'::text,'Mit eszik a parton? Tojást és kenyeret.'::text),
(315885,35099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er steht am Ufer ... der Morgensonne.'::text,'in'::text,'auf'::text,'an'::text,'Er steht am Ufer in der Morgensonne.'::text),
(315889,35099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він стоїть на березі ... ранковому сонці.'::text,'на'::text,'на'::text,'біля'::text,'Він стоїть на березі на ранковому сонці.'::text),
(315888,35099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está de pie en la orilla ... el sol de la mañana.'::text,'bajo'::text,'sobre'::text,'a'::text,'Está de pie en la orilla bajo el sol de la mañana.'::text),
(315887,35099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se tient sur la rive ... soleil du matin.'::text,'au'::text,'sur le'::text,'au'::text,'Il se tient sur la rive au soleil du matin.'::text),
(315890,35099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabah güneşinin ... kıyıda duruyor.'::text,'altında'::text,'üstünde'::text,NULL::text,'Sabah güneşinin altında kıyıda duruyor.'::text),
(315891,35099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parton áll a reggeli ...'::text,'napsütésben'::text,'napsütésen'::text,'napsütésnél'::text,'A parton áll a reggeli napsütésben.'::text),
(315894,35100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schlägt am Ufer ... Eier in eine Pfanne.'::text,'zwei'::text,'zweite'::text,'zweimal'::text,'Er schlägt am Ufer zwei Eier in eine Pfanne.'::text),
(315898,35100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він розбиває на березі ... яйця в сковорідку.'::text,'два'::text,'другі'::text,'двічі'::text,'Він розбиває на березі два яйця в сковорідку.'::text),
(315897,35100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Casca ... huevos en una sartén en la orilla.'::text,'dos'::text,'segundos'::text,'dos veces'::text,'Casca dos huevos en una sartén en la orilla.'::text),
(315896,35100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il casse ... œufs dans une poêle sur la rive.'::text,'deux'::text,'deuxièmes'::text,'deux fois'::text,'Il casse deux œufs dans une poêle sur la rive.'::text),
(315899,35100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyıda ... yumurtayı tavaya kırıyor.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Kıyıda iki yumurtayı tavaya kırıyor.'::text),
(315900,35100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parton ... tojást üt egy serpenyőbe.'::text,'két'::text,'második'::text,'kétszer'::text,'A parton két tojást üt egy serpenyőbe.'::text),
(315912,35102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich beeindruckend: Du kochst zu Hause, aber gestern ... du an einem Ufer.'::text,'kochtest'::text,'kochst'::text,NULL::text,'Ehrlich beeindruckend: Du kochst zu Hause, aber gestern kochtest du an einem Ufer.'::text),
(315916,35102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лоукі вражає: ти готуєш удома, а вчора ... на березі.'::text,'готував'::text,'готуєш'::text,NULL::text,'Лоукі вражає: ти готуєш удома, а вчора готував на березі.'::text),
(315915,35102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me flipa un poco: cocinas en casa, pero ayer ... en una orilla.'::text,'cocinaste'::text,'cocinas'::text,NULL::text,'Me flipa un poco: cocinas en casa, pero ayer cocinaste en una orilla.'::text),
(315914,35102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Discrètement impressionnant : tu cuisines à la maison, mais hier tu ... sur une rive.'::text,'as cuisiné'::text,'cuisines'::text,NULL::text,'Discrètement impressionnant : tu cuisines à la maison, mais hier tu as cuisiné sur une rive.'::text),
(315917,35102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası etkileyici: evde yemek yaparsın ama dün bir kıyıda ...'::text,'yemek yaptın'::text,'yemek yaparsın'::text,NULL::text,'Açıkçası etkileyici: evde yemek yaparsın ama dün bir kıyıda yemek yaptın.'::text),
(315918,35102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey lenyűgöző: otthon főzöl, de tegnap egy parton ...'::text,'főztél'::text,'főzöl'::text,NULL::text,'Lowkey lenyűgöző: otthon főzöl, de tegnap egy parton főztél.'::text),
(315921,35103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Du ... gerade Eier am Ufer.'::text,'isst'::text,'isst'::text,'isst'::text,'Irgendwie ikonisch: Du isst gerade Eier am Ufer.'::text),
(315925,35103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи легендарно: ти саме зараз ... яйця на березі.'::text,'їси'::text,'їсть'::text,'їси'::text,'Трохи легендарно: ти саме зараз їси яйця на березі.'::text),
(315924,35103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco icónico: ahora mismo ... huevos en la orilla.'::text,'estás comiendo'::text,'come'::text,'estás comiendo'::text,'Un poco icónico: ahora mismo estás comiendo huevos en la orilla.'::text),
(315923,35103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique : tu ... des œufs sur la rive en ce moment.'::text,'es en train de manger'::text,'mange'::text,'es en train de manger'::text,'Un peu iconique : tu es en train de manger des œufs sur la rive en ce moment.'::text),
(315926,35103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz efsane: şu an kıyıda yumurta ...'::text,'yiyorsun'::text,'yer'::text,'yiyorsun'::text,'Biraz efsane: şu an kıyıda yumurta yiyorsun.'::text),
(315927,35103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit ikonikus: most épp tojást ... a parton.'::text,'eszel'::text,'eszik'::text,'eszel'::text,'Kicsit ikonikus: most épp tojást eszel a parton.'::text),
(314706,34968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, er fährt nie, aber heute Abend ... er auf dem Fahrersitz.'::text,'sitzt'::text,'sitzt'::text,NULL::text,'Nee Bro, er fährt nie, aber heute Abend sitzt er auf dem Fahrersitz.'::text),
(314710,34968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, він ніколи не кермує, але сьогодні ввечері ... на місці водія.'::text,'сидить'::text,'сидить'::text,NULL::text,'Не, бро, він ніколи не кермує, але сьогодні ввечері сидить на місці водія.'::text),
(314709,34968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, él nunca conduce, pero esta noche ... en el asiento del conductor.'::text,'está sentado'::text,'se sienta'::text,NULL::text,'Qué va, tío, él nunca conduce, pero esta noche está sentado en el asiento del conductor.'::text),
(314708,34968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, il ne conduit jamais, mais ce soir il ... sur le siège conducteur.'::text,'est assis'::text,'s''assoit'::text,NULL::text,'Nan frère, il ne conduit jamais, mais ce soir il est assis sur le siège conducteur.'::text),
(314711,34968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o hiç araba sürmez ama bu gece şoför koltuğunda ...'::text,'oturuyor'::text,'oturur'::text,NULL::text,'Yok kanka, o hiç araba sürmez ama bu gece şoför koltuğunda oturuyor.'::text),
(314712,34968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, sosem vezet, de ma este a sofőrülésen ...'::text,'ül'::text,'ül'::text,NULL::text,'Nem, tesó, sosem vezet, de ma este a sofőrülésen ül.'::text),
(314715,34969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prognose: Der Hund auf dem Fahrersitz ... heute Abend 50 Kilometer fahren.'::text,'wird'::text,'ist'::text,'war'::text,'Prognose: Der Hund auf dem Fahrersitz wird heute Abend 50 Kilometer fahren.'::text),
(314719,34969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прогноз: пес на місці водія сьогодні ввечері ... їхати 50 кілометрів.'::text,'буде'::text,'є'::text,'був'::text,'Прогноз: пес на місці водія сьогодні ввечері буде їхати 50 кілометрів.'::text),
(314718,34969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Previsión: el perro del asiento del conductor ... 50 kilómetros esta noche.'::text,'conducirá'::text,'está'::text,'estaba'::text,'Previsión: el perro del asiento del conductor conducirá 50 kilómetros esta noche.'::text),
(314717,34969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prévision : le chien sur le siège conducteur ... 50 kilomètres ce soir.'::text,'conduira'::text,'est'::text,'était'::text,'Prévision : le chien sur le siège conducteur conduira 50 kilomètres ce soir.'::text),
(314720,34969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin: şoför koltuğundaki köpek bu gece 50 kilometre ...'::text,'sürecek'::text,NULL::text,'idi'::text,'Tahmin: şoför koltuğundaki köpek bu gece 50 kilometre sürecek.'::text),
(314721,34969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előrejelzés: a sofőrülésen ülő kutya ma este 50 kilométert ... vezetni.'::text,'fog'::text,'van'::text,'volt'::text,'Előrejelzés: a sofőrülésen ülő kutya ma este 50 kilométert fog vezetni.'::text),
(314733,34971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund auf dem Fahrersitz hält das Lenkrad. Er ... losfahren.'::text,'wird'::text,'wird'::text,NULL::text,'Der Hund auf dem Fahrersitz hält das Lenkrad. Er wird losfahren.'::text),
(314737,34971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес на місці водія тримає кермо. Він ... рушити.'::text,'збирається'::text,'буде'::text,NULL::text,'Пес на місці водія тримає кермо. Він збирається рушити.'::text),
(314736,34971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro del asiento del conductor sujeta el volante. ... arrancar.'::text,'Va a'::text,NULL::text,NULL::text,'El perro del asiento del conductor sujeta el volante. Va a arrancar.'::text),
(314735,34971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien sur le siège conducteur tient le volant. Il ... démarrer.'::text,'va'::text,NULL::text,NULL::text,'Le chien sur le siège conducteur tient le volant. Il va démarrer.'::text),
(314738,34971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoför koltuğundaki köpek direksiyonu tutuyor. Yola ...'::text,'çıkacak'::text,'çıkacak'::text,NULL::text,'Şoför koltuğundaki köpek direksiyonu tutuyor. Yola çıkacak.'::text),
(314739,34971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőrülésen ülő kutya fogja a kormányt. El ... indulni.'::text,'fog'::text,'fog'::text,NULL::text,'A sofőrülésen ülő kutya fogja a kormányt. El fog indulni.'::text),
(314742,34972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass sie so viel ... auf den Sitzen hinterlassen haben.'::text,'Schlamm'::text,'Schlamm'::text,'einen Schlamm'::text,'Bestie, er hat mir erzählt, dass sie so viel Schlamm auf den Sitzen hinterlassen haben.'::text),
(314746,34972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він мені сказав, що вони лишили стільки ... на сидіннях.'::text,'багнюки'::text,'багнюки'::text,'багнюки'::text,'Подруго, він мені сказав, що вони лишили стільки багнюки на сидіннях.'::text),
(314745,34972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que dejaron tanto ... en los asientos.'::text,'barro'::text,'barro'::text,'un barro'::text,'Tía, me dijo que dejaron tanto barro en los asientos.'::text),
(314744,34972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''ils ont laissé tellement de ... sur les sièges.'::text,'boue'::text,'boue'::text,'une boue'::text,'Ma belle, il m''a dit qu''ils ont laissé tellement de boue sur les sièges.'::text),
(314747,34972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana koltuklarda o kadar çok ... bıraktıklarını söyledi.'::text,'çamur'::text,'çamurlar'::text,'bir çamur'::text,'Kanka, bana koltuklarda o kadar çok çamur bıraktıklarını söyledi.'::text),
(314748,34972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, annyi ... hagytak az üléseken.'::text,'sarat'::text,'sarat'::text,'egy sarat'::text,'Csajszi, azt mondta, annyi sarat hagytak az üléseken.'::text),
(314751,34973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Arbeit, Herr Wachtmeister. Die Hunde auf ihren Sitzen gaben sehr ... Antworten.'::text,'wenige'::text,'wenig'::text,'viel'::text,'Tolle Arbeit, Herr Wachtmeister. Die Hunde auf ihren Sitzen gaben sehr wenige Antworten.'::text),
(314755,34973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, офіцере. Пси на своїх сидіннях дали дуже ... відповідей.'::text,'мало'::text,'мало'::text,'багато'::text,'Чудова робота, офіцере. Пси на своїх сидіннях дали дуже мало відповідей.'::text),
(314754,34973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, agente. Los perros en sus asientos dieron muy ... respuestas.'::text,'pocas'::text,'poco'::text,'mucho'::text,'Buen trabajo, agente. Los perros en sus asientos dieron muy pocas respuestas.'::text),
(314753,34973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail, agent. Les chiens sur leurs sièges ont donné très ... réponses.'::text,'peu de'::text,'peu de'::text,'beaucoup de'::text,'Beau travail, agent. Les chiens sur leurs sièges ont donné très peu de réponses.'::text),
(314756,34973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, memur bey. Koltuklarındaki köpekler çok ... cevap verdi.'::text,'az'::text,'az'::text,'çok'::text,'Harika iş, memur bey. Koltuklarındaki köpekler çok az cevap verdi.'::text),
(314757,34973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, biztos úr. Az ülésükön ülő kutyák nagyon ... választ adtak.'::text,'kevés'::text,'kevés'::text,'sok'::text,'Szép munka, biztos úr. Az ülésükön ülő kutyák nagyon kevés választ adtak.'::text),
(314760,34974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, eine ganz normale Nacht: Auf den Vordersitzen ... zwei Hunde.'::text,'sind'::text,'ist'::text,'sein'::text,'Klar, eine ganz normale Nacht: Auf den Vordersitzen sind zwei Hunde.'::text),
(314764,34974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, звичайна ніч: на передніх сидіннях ... два пси.'::text,'є'::text,'є'::text,'бути'::text,'Звісно, звичайна ніч: на передніх сидіннях є два пси.'::text),
(314763,34974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, una noche normal: ... dos perros en los asientos delanteros.'::text,'hay'::text,'hay'::text,'hay'::text,'Obviamente, una noche normal: hay dos perros en los asientos delanteros.'::text),
(314762,34974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, une nuit normale : ... deux chiens sur les sièges avant.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Évidemment, une nuit normale : il y a deux chiens sur les sièges avant.'::text),
(314765,34974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki normal bir gece: ön koltuklarda iki köpek ...'::text,'var'::text,'var'::text,'olmak'::text,'Tabii ki normal bir gece: ön koltuklarda iki köpek var.'::text),
(314766,34974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egy átlagos éjszaka: az első üléseken két kutya ...'::text,'van'::text,'van'::text,'lenni'::text,'Nyilván egy átlagos éjszaka: az első üléseken két kutya van.'::text),
(314769,34975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Befehl vom Cop: Der Hund ... vom Sitz runter, echt.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, Befehl vom Cop: Der Hund muss vom Sitz runter, echt.'::text),
(314773,34975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, наказ копа: пес ... злізти з сидіння, чесно.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бро, наказ копа: пес має злізти з сидіння, чесно.'::text),
(314772,34975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, órdenes del poli: el perro ... bajarse del asiento, en serio.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, órdenes del poli: el perro tiene que bajarse del asiento, en serio.'::text),
(314771,34975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ordre du flic : le chien ... descendre du siège, sérieux.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, ordre du flic : le chien doit descendre du siège, sérieux.'::text),
(314774,34975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, polisin emri: köpek koltuktan ..., cidden.'::text,'inmek zorunda'::text,'inmeli'::text,'inmeli'::text,'Kanka, polisin emri: köpek koltuktan inmek zorunda, cidden.'::text),
(314775,34975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, zsaruparancs: a kutyának ki ... szállnia az ülésből, komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, zsaruparancs: a kutyának ki kell szállnia az ülésből, komolyan.'::text),
(327594,36400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Pick-up ... ein Fenster voller Rauch!'::text,'hat'::text,'haben'::text,'hat'::text,'Katastrophe! Der Pick-up hat ein Fenster voller Rauch!'::text),
(327598,36400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Пікап ... вікно, повне диму!'::text,'має'::text,'мати'::text,'має'::text,'Катастрофа! Пікап має вікно, повне диму!'::text),
(327597,36400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡La camioneta ... una ventanilla llena de humo!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Desastre! ¡La camioneta tiene una ventanilla llena de humo!'::text),
(327596,36400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Le pick-up ... une vitre pleine de fumée !'::text,'a'::text,'ont'::text,'a'::text,'Catastrophe ! Le pick-up a une vitre pleine de fumée !'::text),
(327599,36400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Kamyonetin dumanla dolu bir camı ...!'::text,'var'::text,'var'::text,'var'::text,'Felaket! Kamyonetin dumanla dolu bir camı var!'::text),
(327600,36400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A pickupnak füsttel teli ablaka ...!'::text,'van'::text,'van'::text,'van'::text,'Katasztrófa! A pickupnak füsttel teli ablaka van!'::text),
(327603,36401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fenster ... klar, und zwei Hunde schauen heraus.'::text,'wird'::text,'werden'::text,'werdend'::text,'Das Fenster wird klar, und zwei Hunde schauen heraus.'::text),
(327607,36401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вікно ... прозорим, і два пси визирають назовні.'::text,'стає'::text,'ставати'::text,'стаючи'::text,'Вікно стає прозорим, і два пси визирають назовні.'::text),
(327606,36401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ventanilla ... transparente y dos perros se asoman.'::text,'se vuelve'::text,'volverse'::text,'volviéndose'::text,'La ventanilla se vuelve transparente y dos perros se asoman.'::text),
(327605,36401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vitre ... claire, et deux chiens regardent dehors.'::text,'devient'::text,'devenir'::text,'devenant'::text,'La vitre devient claire, et deux chiens regardent dehors.'::text),
(327608,36401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam ... ve iki köpek dışarı bakıyor.'::text,'netleşir'::text,'netleşmek'::text,'netleşerek'::text,'Cam netleşir ve iki köpek dışarı bakıyor.'::text),
(327609,36401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ablak ... tisztává, és két kutya kinéz.'::text,'válik'::text,'válni'::text,'váló'::text,'Az ablak válik tisztává, és két kutya kinéz.'::text),
(327612,36402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand ... die Hunde durch das beschlagene Fenster sehen.'::text,'kann'::text,'ist'::text,'sind'::text,'Niemand kann die Hunde durch das beschlagene Fenster sehen.'::text),
(327616,36402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не ... бачити псів крізь запітніле вікно.'::text,'може'::text,'є'::text,'є'::text,'Ніхто не може бачити псів крізь запітніле вікно.'::text),
(327615,36402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie ... ver a los perros a través de la ventanilla empañada.'::text,'puede'::text,'está'::text,'están'::text,'Nadie puede ver a los perros a través de la ventanilla empañada.'::text),
(327614,36402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne ... voir les chiens à travers la vitre embuée.'::text,'peut'::text,'est'::text,'sont'::text,'Personne ne peut voir les chiens à travers la vitre embuée.'::text),
(327617,36402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse buğulu camdan köpekleri ...'::text,'göremez'::text,NULL::text,NULL::text,'Kimse buğulu camdan köpekleri göremez.'::text),
(327618,36402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem ... látni a kutyákat a bepárásodott ablakon át.'::text,'tudja'::text,'van'::text,'vannak'::text,'Senki sem tudja látni a kutyákat a bepárásodott ablakon át.'::text),
(327621,36403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sitzen hinter dem Fenster des Pick-ups.'::text,'2 Hunde'::text,'2 Hund'::text,'2 Hunde'::text,'2 Hunde sitzen hinter dem Fenster des Pick-ups.'::text),
(327625,36403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... сидять за вікном пікапа.'::text,'2 пси'::text,'2 пес'::text,'2 пси'::text,'2 пси сидять за вікном пікапа.'::text),
(327624,36403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... están sentados detrás de la ventanilla de la camioneta.'::text,'2 perros'::text,'2 perro'::text,'2 perros'::text,'2 perros están sentados detrás de la ventanilla de la camioneta.'::text),
(327623,36403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sont assis derrière la vitre du pick-up.'::text,'2 chiens'::text,'2 chien'::text,'2 chiens'::text,'2 chiens sont assis derrière la vitre du pick-up.'::text),
(327626,36403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kamyonetin camının arkasında oturuyor.'::text,'2 köpek'::text,'2 köpek'::text,'2 köpekler'::text,'2 köpek kamyonetin camının arkasında oturuyor.'::text),
(327627,36403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ül a pickup ablaka mögött.'::text,'2 kutya'::text,'2 kutya'::text,'2 kutya'::text,'2 kutya ül a pickup ablaka mögött.'::text),
(327630,36404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pick-up hat ein Seitenfenster, und ... Fenster ist beschlagen.'::text,'das'::text,'ein'::text,'ein'::text,'Der Pick-up hat ein Seitenfenster, und das Fenster ist beschlagen.'::text),
(327634,36404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У пікапа є бокове вікно, і ... вікно запітніле.'::text,''::text,NULL::text,NULL::text,'У пікапа є бокове вікно, і вікно запітніле.'::text),
(327633,36404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La camioneta tiene una ventanilla lateral, y ... ventanilla está empañada.'::text,'la'::text,'una'::text,'una'::text,'La camioneta tiene una ventanilla lateral, y la ventanilla está empañada.'::text),
(327632,36404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pick-up a une vitre latérale, et ... vitre est embuée.'::text,'la'::text,'une'::text,'une'::text,'Le pick-up a une vitre latérale, et la vitre est embuée.'::text),
(327635,36404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamyonetin bir yan camı var ve ... cam buğulu.'::text,''::text,'bir'::text,'bir'::text,'Kamyonetin bir yan camı var ve cam buğulu.'::text),
(327636,36404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pickupnak van egy oldalablaka, és ... ablak párás.'::text,'az'::text,'egy'::text,'egy'::text,'A pickupnak van egy oldalablaka, és az ablak párás.'::text),
(327639,36405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... Fenster wird gleich klar.'::text,'jenes'::text,'jene'::text,'diese'::text,'Bro, jenes Fenster wird gleich klar.'::text),
(327643,36405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... вікно скоро стане прозорим.'::text,'те'::text,'ті'::text,'ці'::text,'Бро, те вікно скоро стане прозорим.'::text),
(327642,36405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... ventanilla se va a desempañar pronto.'::text,'esa'::text,'esas'::text,'estas'::text,'Tío, esa ventanilla se va a desempañar pronto.'::text),
(327641,36405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... vitre va bientôt se désembuer.'::text,'cette'::text,'ces'::text,'ces'::text,'Frère, cette vitre va bientôt se désembuer.'::text),
(327644,36405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... cam birazdan açılacak.'::text,'şu'::text,'şu'::text,'bu'::text,'Kanka, şu cam birazdan açılacak.'::text),
(327645,36405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... az ablak mindjárt kitisztul.'::text,'az'::text,'azok'::text,'ezek'::text,'Tesó, az az ablak mindjárt kitisztul.'::text),
(327657,36407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Das Fenster blieb 10 Sekunden beschlagen, ... der Nebel dicht war.'::text,'weil'::text,'aber'::text,'also'::text,'Bericht: Das Fenster blieb 10 Sekunden beschlagen, weil der Nebel dicht war.'::text),
(327661,36407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: вікно лишалося запітнілим 10 секунд, ... туман був густий.'::text,'бо'::text,'але'::text,'тому'::text,'Звіт: вікно лишалося запітнілим 10 секунд, бо туман був густий.'::text),
(327660,36407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: la ventanilla estuvo empañada 10 segundos ... la niebla era espesa.'::text,'porque'::text,'pero'::text,'así que'::text,'Informe: la ventanilla estuvo empañada 10 segundos porque la niebla era espesa.'::text),
(327659,36407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : la vitre est restée embuée pendant 10 secondes ... la buée était épaisse.'::text,'parce que'::text,'mais'::text,'donc'::text,'Rapport : la vitre est restée embuée pendant 10 secondes parce que la buée était épaisse.'::text),
(327662,36407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: cam 10 saniye buğulu kaldı ... sis yoğundu.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Rapor: cam 10 saniye buğulu kaldı çünkü sis yoğundu.'::text),
(327663,36407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: az ablak 10 másodpercig párás maradt, ... sűrű volt a köd.'::text,'mert'::text,'de'::text,'ezért'::text,'Jelentés: az ablak 10 másodpercig párás maradt, mert sűrű volt a köd.'::text),
(316101,35123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hält vor der Show ... silbernen Ball.'::text,'seinen'::text,'ihren'::text,'seinen'::text,'Der Mann hält vor der Show seinen silbernen Ball.'::text),
(316105,35123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік тримає перед шоу ... срібний м''яч.'::text,'свій'::text,'свій'::text,'свій'::text,'Чоловік тримає перед шоу свій срібний м''яч.'::text),
(316104,35123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre sujeta ... pelota plateada antes del espectáculo.'::text,'su'::text,'su'::text,'su'::text,'El hombre sujeta su pelota plateada antes del espectáculo.'::text),
(316103,35123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme tient ... ballon argenté avant le spectacle.'::text,'son'::text,'son'::text,'son'::text,'L''homme tient son ballon argenté avant le spectacle.'::text),
(316106,35123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam gösteriden önce ... gümüş topunu tutuyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam gösteriden önce onun gümüş topunu tutuyor.'::text),
(316107,35123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi a show előtt az ezüst ... tartja.'::text,'labdáját'::text,'labdáját'::text,'labdáját'::text,'A férfi a show előtt az ezüst labdáját tartja.'::text),
(316110,35124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... macht der Delfin in der Show? Einen Fallrückzieher.'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was macht der Delfin in der Show? Einen Fallrückzieher.'::text),
(316114,35124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... робить дельфін у шоу? Удар через себе.'::text,'Що'::text,'Хто'::text,'Де'::text,'Що робить дельфін у шоу? Удар через себе.'::text),
(316113,35124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... hace el delfín en el espectáculo? Una chilena.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué hace el delfín en el espectáculo? Una chilena.'::text),
(316112,35124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fait le dauphin dans le spectacle ? Un retourné acrobatique.'::text,'Que'::text,'Qui'::text,'Où'::text,'Que fait le dauphin dans le spectacle ? Un retourné acrobatique.'::text),
(316115,35124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yunus gösteride ... yapıyor? Rövaşata.'::text,'ne'::text,'kim'::text,'nerede'::text,'Yunus gösteride ne yapıyor? Rövaşata.'::text),
(316116,35124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... csinál a delfin a showban? Ollózást.'::text,'Mit'::text,'Ki'::text,'Hol'::text,'Mit csinál a delfin a showban? Ollózást.'::text),
(316128,35126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Show hat ... Delfin und einen Mann.'::text,'einen'::text,'ersten'::text,'einmal'::text,'Die Show hat einen Delfin und einen Mann.'::text),
(316132,35126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У шоу ... дельфін і один чоловік.'::text,'один'::text,'перший'::text,'раз'::text,'У шоу один дельфін і один чоловік.'::text),
(316131,35126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El espectáculo tiene ... delfín y un hombre.'::text,'un'::text,'primer'::text,'una vez'::text,'El espectáculo tiene un delfín y un hombre.'::text),
(316130,35126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spectacle a ... dauphin et un homme.'::text,'un'::text,'premier'::text,'une fois'::text,'Le spectacle a un dauphin et un homme.'::text),
(316133,35126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gösteride ... yunus ve bir adam var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Gösteride bir yunus ve bir adam var.'::text),
(316134,35126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A showban ... delfin és egy férfi van.'::text,'egy'::text,'első'::text,'egyszer'::text,'A showban egy delfin és egy férfi van.'::text),
(316137,35127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Show ... mit dem Ball für immer verloren!'::text,'endete'::text,'endet'::text,'enden'::text,'Katastrophe! Die Show endete mit dem Ball für immer verloren!'::text),
(316141,35127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Шоу ..., а м''яч утрачено назавжди!'::text,'закінчилося'::text,'закінчується'::text,'закінчитися'::text,'Катастрофа! Шоу закінчилося, а м''яч утрачено назавжди!'::text),
(316140,35127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡El espectáculo ... con la pelota perdida para siempre!'::text,'terminó'::text,'termina'::text,'terminar'::text,'¡Desastre! ¡El espectáculo terminó con la pelota perdida para siempre!'::text),
(316139,35127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Le spectacle ... avec le ballon perdu pour toujours !'::text,'s''est terminé'::text,'se termine'::text,'se terminer'::text,'Catastrophe ! Le spectacle s''est terminé avec le ballon perdu pour toujours !'::text),
(316142,35127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Gösteri top sonsuza dek kaybolarak ...!'::text,'bitti'::text,'biter'::text,'bitmek'::text,'Felaket! Gösteri top sonsuza dek kaybolarak bitti!'::text),
(316143,35127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A show úgy ..., hogy a labda örökre elveszett!'::text,'ért véget'::text,'ér véget'::text,'véget érni'::text,'Katasztrófa! A show úgy ért véget, hogy a labda örökre elveszett!'::text),
(316146,35128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Delfin hört sonst zu, aber gestern ... er die Show!'::text,'stahl'::text,'stiehlt'::text,NULL::text,'Katastrophe! Der Delfin hört sonst zu, aber gestern stahl er die Show!'::text),
(316150,35128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Дельфін зазвичай слухається, але вчора ... усе шоу!'::text,'вкрав'::text,'краде'::text,NULL::text,'Катастрофа! Дельфін зазвичай слухається, але вчора вкрав усе шоу!'::text),
(316149,35128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! El delfín suele escuchar, ¡pero ayer ... todo el protagonismo del espectáculo!'::text,'se llevó'::text,'se lleva'::text,NULL::text,'¡Desastre! El delfín suele escuchar, ¡pero ayer se llevó todo el protagonismo del espectáculo!'::text),
(316148,35128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! D''habitude, le dauphin écoute, mais hier il ... la vedette pendant le spectacle !'::text,'a volé'::text,'vole'::text,NULL::text,'Catastrophe ! D''habitude, le dauphin écoute, mais hier il a volé la vedette pendant le spectacle !'::text),
(316151,35128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Yunus genelde söz dinler ama dün gösteride tüm ilgiyi ...!'::text,'çaldı'::text,'çalar'::text,NULL::text,'Felaket! Yunus genelde söz dinler ama dün gösteride tüm ilgiyi çaldı!'::text),
(316152,35128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A delfin általában szót fogad, de tegnap ... a showt!'::text,'ellopta'::text,'ellopja'::text,NULL::text,'Katasztrófa! A delfin általában szót fogad, de tegnap ellopta a showt!'::text),
(316164,35130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass der Delfin sonst ausruht, aber jetzt ... er eine Show.'::text,'macht'::text,'macht'::text,NULL::text,'Hör zu, er hat mir erzählt, dass der Delfin sonst ausruht, aber jetzt macht er eine Show.'::text),
(316168,35130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що дельфін зазвичай відпочиває, а зараз ... шоу.'::text,'влаштовує'::text,'влаштовує'::text,NULL::text,'Слухай, він мені сказав, що дельфін зазвичай відпочиває, а зараз влаштовує шоу.'::text),
(316167,35130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que el delfín suele descansar, pero ahora ... un espectáculo.'::text,'está haciendo'::text,'hace'::text,NULL::text,'Oye, me dijo que el delfín suele descansar, pero ahora está haciendo un espectáculo.'::text),
(316166,35130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que le dauphin se repose d''habitude, mais que là, il ... un spectacle.'::text,'est en train de faire'::text,'fait'::text,NULL::text,'Écoute, il m''a dit que le dauphin se repose d''habitude, mais que là, il est en train de faire un spectacle.'::text),
(316169,35130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, dedi ki yunus genelde dinlenir ama şimdi bir gösteri ...'::text,'yapıyor'::text,'yapar'::text,NULL::text,'Dinle, dedi ki yunus genelde dinlenir ama şimdi bir gösteri yapıyor.'::text),
(316170,35130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a delfin általában pihen, de most egy showt ...'::text,'csinál'::text,'csinál'::text,NULL::text,'Figyelj, azt mondta, hogy a delfin általában pihen, de most egy showt csinál.'::text),
(319827,35537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Steinbrücke ... noch viele Jahre stehen.'::text,'wird'::text,'ist'::text,'war'::text,'Diese Steinbrücke wird noch viele Jahre stehen.'::text),
(319831,35537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей кам''яний міст ... стояти ще багато років.'::text,'буде'::text,'є'::text,'був'::text,'Цей кам''яний міст буде стояти ще багато років.'::text),
(319830,35537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este puente de piedra ... en pie muchos años más.'::text,'seguirá'::text,'está'::text,'estaba'::text,'Este puente de piedra seguirá en pie muchos años más.'::text),
(319829,35537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce pont de pierre ... debout encore de nombreuses années.'::text,'tiendra'::text,'est'::text,'était'::text,'Ce pont de pierre tiendra debout encore de nombreuses années.'::text),
(319832,35537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu taş köprü daha uzun yıllar ...'::text,'ayakta kalacak'::text,NULL::text,'idi'::text,'Bu taş köprü daha uzun yıllar ayakta kalacak.'::text),
(319833,35537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a kőhíd még sok évig ... állni.'::text,'fog'::text,'van'::text,'volt'::text,'Ez a kőhíd még sok évig fog állni.'::text),
(319836,35538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zug ist auf der Steinbrücke, also ... er sie überqueren.'::text,'wird'::text,'wird'::text,'wird'::text,'Der Zug ist auf der Steinbrücke, also wird er sie überqueren.'::text),
(319840,35538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Потяг на кам''яному мосту, тож він ... його перетнути.'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Потяг на кам''яному мосту, тож він збирається його перетнути.'::text),
(319839,35538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tren está en el puente de piedra, así que ... cruzarlo.'::text,'va a'::text,'va a'::text,'va a'::text,'El tren está en el puente de piedra, así que va a cruzarlo.'::text),
(319838,35538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le train est sur le pont de pierre, donc il ... le traverser.'::text,'va'::text,'va'::text,'va'::text,'Le train est sur le pont de pierre, donc il va le traverser.'::text),
(319841,35538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren taş köprünün üstünde, bu yüzden onu ...'::text,'geçecek'::text,'geçecek'::text,'geçecek'::text,'Tren taş köprünün üstünde, bu yüzden onu geçecek.'::text),
(319842,35538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vonat a kőhídon van, ezért át ... kelni rajta.'::text,'fog'::text,'fog'::text,'fog'::text,'A vonat a kőhídon van, ezért át fog kelni rajta.'::text),
(319845,35539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wasserfall ist hinter der Steinbrücke, also ... die Brücke nass werden.'::text,'wird'::text,'wird'::text,NULL::text,'Der Wasserfall ist hinter der Steinbrücke, also wird die Brücke nass werden.'::text),
(319849,35539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водоспад за кам''яним мостом, тож міст ... намокнути.'::text,'збирається'::text,'буде'::text,NULL::text,'Водоспад за кам''яним мостом, тож міст збирається намокнути.'::text),
(319848,35539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cascada está detrás del puente de piedra, así que el puente ... mojarse.'::text,'va a'::text,NULL::text,NULL::text,'La cascada está detrás del puente de piedra, así que el puente va a mojarse.'::text),
(319847,35539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cascade est derrière le pont de pierre, donc le pont ... être mouillé.'::text,'va'::text,NULL::text,NULL::text,'La cascade est derrière le pont de pierre, donc le pont va être mouillé.'::text),
(319850,35539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şelale taş köprünün arkasında, bu yüzden köprü ...'::text,'ıslanacak'::text,'ıslanacak'::text,NULL::text,'Şelale taş köprünün arkasında, bu yüzden köprü ıslanacak.'::text),
(319851,35539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vízesés a kőhíd mögött van, ezért a híd vizes ... lenni.'::text,'fog'::text,'fog'::text,NULL::text,'A vízesés a kőhíd mögött van, ezért a híd vizes fog lenni.'::text),
(319854,35540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut riesig! Diese Brücke besteht aus so viel ...!'::text,'Stein'::text,'Stein'::text,'einem Stein'::text,'Absolut riesig! Diese Brücke besteht aus so viel Stein!'::text),
(319858,35540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто гігантський! Цей міст збудований із такої кількості ...!'::text,'каменю'::text,'каменів'::text,'каменю'::text,'Просто гігантський! Цей міст збудований із такої кількості каменю!'::text),
(319857,35540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente enorme! ¡Este puente está hecho de tanta ...!'::text,'piedra'::text,'piedra'::text,'una piedra'::text,'¡Absolutamente enorme! ¡Este puente está hecho de tanta piedra!'::text),
(319856,35540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument énorme ! Ce pont est fait de tellement de ... !'::text,'pierre'::text,'pierre'::text,'une pierre'::text,'Absolument énorme ! Ce pont est fait de tellement de pierre !'::text),
(319859,35540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen devasa! Bu köprünün yapımında o kadar çok ... kullanılmış ki!'::text,'taş'::text,'taşlar'::text,'bir taş'::text,'Resmen devasa! Bu köprünün yapımında o kadar çok taş kullanılmış ki!'::text),
(319860,35540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút hatalmas! Ez a híd annyi ... készült!'::text,'kőből'::text,'kőből'::text,'egy kőből'::text,'Abszolút hatalmas! Ez a híd annyi kőből készült!'::text),
(319872,35542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, hinter jener Steinbrücke ... ein Wasserfall.'::text,'ist'::text,'sind'::text,'sein'::text,'Rate mal, ich hab gehört, hinter jener Steinbrücke ist ein Wasserfall.'::text),
(319876,35542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що за тим кам''яним мостом ... водоспад.'::text,'є'::text,'є'::text,'бути'::text,'Уяви, я чула, що за тим кам''яним мостом є водоспад.'::text),
(319875,35542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, he oído que ... una cascada detrás de ese puente de piedra.'::text,'hay'::text,'hay'::text,'hay'::text,'Adivina, he oído que hay una cascada detrás de ese puente de piedra.'::text),
(319874,35542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire que derrière ce pont de pierre, ... une cascade.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Devine quoi, j''ai entendu dire que derrière ce pont de pierre, il y a une cascade.'::text),
(319877,35542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duydum ki o taş köprünün arkasında bir şelale ...'::text,'var'::text,'var'::text,'olmak'::text,'Bil bakalım, duydum ki o taş köprünün arkasında bir şelale var.'::text),
(319878,35542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy amögött a kőhíd mögött ... egy vízesés.'::text,'van'::text,'vannak'::text,'lenni'::text,'Képzeld, azt hallottam, hogy amögött a kőhíd mögött van egy vízesés.'::text),
(319881,35543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr entspannend, klar: Mit nur einem Gleis ... der Zug über die Steinbrücke fahren.'::text,'muss'::text,'muss'::text,'sollte'::text,'Sehr entspannend, klar: Mit nur einem Gleis muss der Zug über die Steinbrücke fahren.'::text),
(319885,35543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже заспокійливо, звісно: з однією колією потяг ... перетнути кам''яний міст.'::text,'має'::text,'мусить'::text,'мав би'::text,'Дуже заспокійливо, звісно: з однією колією потяг має перетнути кам''яний міст.'::text),
(319884,35543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy relajante, obviamente: con una sola vía, el tren ... cruzar el puente de piedra.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Muy relajante, obviamente: con una sola vía, el tren tiene que cruzar el puente de piedra.'::text),
(319883,35543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très relaxant, évidemment : avec une seule voie, le train ... traverser le pont de pierre.'::text,'doit'::text,'doit'::text,'devrait'::text,'Très relaxant, évidemment : avec une seule voie, le train doit traverser le pont de pierre.'::text),
(319886,35543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok rahatlatıcı, tabii: tek hat varken tren taş köprüden ...'::text,'geçmek zorunda'::text,'geçmeli'::text,'geçmeli'::text,'Çok rahatlatıcı, tabii: tek hat varken tren taş köprüden geçmek zorunda.'::text),
(319887,35543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon megnyugtató, nyilván: egyetlen vágánnyal a vonatnak át ... kelnie a kőhídon.'::text,'kell'::text,'kell'::text,'kellene'::text,'Nagyon megnyugtató, nyilván: egyetlen vágánnyal a vonatnak át kell kelnie a kőhídon.'::text),
(319890,35544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leute ... wegen des Zugs nicht auf der Steinbrücke laufen.'::text,'sollten'::text,'sollen'::text,'sollten'::text,'Leute sollten wegen des Zugs nicht auf der Steinbrücke laufen.'::text),
(319894,35544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди не ... ходити по кам''яному мосту через потяг.'::text,'мали б'::text,'будуть'::text,'мали б'::text,'Люди не мали б ходити по кам''яному мосту через потяг.'::text),
(319893,35544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente no ... caminar por el puente de piedra por el tren.'::text,'debería'::text,'deberá'::text,'debería'::text,'La gente no debería caminar por el puente de piedra por el tren.'::text),
(319892,35544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens ne ... pas marcher sur le pont de pierre à cause du train.'::text,'devraient'::text,'devront'::text,'devraient'::text,'Les gens ne devraient pas marcher sur le pont de pierre à cause du train.'::text),
(319895,35544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar tren yüzünden taş köprüde ...'::text,'yürümemeli'::text,'yürümeyecek'::text,'yürümemeli'::text,'İnsanlar tren yüzünden taş köprüde yürümemeli.'::text),
(319896,35544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az embereknek a vonat miatt nem ... sétálniuk a kőhídon.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Az embereknek a vonat miatt nem kellene sétálniuk a kőhídon.'::text),
(313392,34822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Sie ... die Rippchen auf einem Stein, nicht im Ofen!'::text,'braten'::text,'brät'::text,'bratend'::text,'Albtraum! Sie braten die Rippchen auf einem Stein, nicht im Ofen!'::text),
(313396,34822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Вони ... ребра на камені, а не в духовці!'::text,'печуть'::text,'пече'::text,'печучи'::text,'Жах! Вони печуть ребра на камені, а не в духовці!'::text),
(313395,34822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... las costillas en una piedra, no en el horno!'::text,'Asan'::text,'Asa'::text,'Asando'::text,'¡Pesadilla! ¡Asan las costillas en una piedra, no en el horno!'::text),
(313394,34822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Ils ... les côtes sur une pierre, pas au four !'::text,'rôtissent'::text,'rôtit'::text,'rôtissant'::text,'Cauchemar ! Ils rôtissent les côtes sur une pierre, pas au four !'::text),
(313397,34822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Kaburgaları fırında değil, taşın üstünde ...!'::text,'kızartırlar'::text,'kızartır'::text,'kızartarak'::text,'Kâbus! Kaburgaları fırında değil, taşın üstünde kızartırlar!'::text),
(313398,34822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Kövön ... a bordát, nem sütőben!'::text,'sütik'::text,'süti'::text,'sütő'::text,'Rémálom! Kövön sütik a bordát, nem sütőben!'::text),
(313410,34824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... braten sie die Rippchen? Auf einem heißen Stein.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo braten sie die Rippchen? Auf einem heißen Stein.'::text),
(313414,34824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вони печуть ребра? На гарячому камені.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де вони печуть ребра? На гарячому камені.'::text),
(313413,34824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... asan las costillas? En una piedra caliente.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde asan las costillas? En una piedra caliente.'::text),
(313412,34824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rôtissent-ils les côtes ? Sur une pierre chaude.'::text,'Où'::text,'Que'::text,'Qui'::text,'Où rôtissent-ils les côtes ? Sur une pierre chaude.'::text),
(313415,34824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaburgaları ... kızartıyorlar? Sıcak bir taşın üstünde.'::text,'nerede'::text,'ne'::text,'kim'::text,'Kaburgaları nerede kızartıyorlar? Sıcak bir taşın üstünde.'::text),
(313416,34824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sütik a bordát? Egy forró kövön.'::text,'Hol'::text,'Mit'::text,'Ki'::text,'Hol sütik a bordát? Egy forró kövön.'::text),
(313419,34825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie die Rippchen über heißer Glut.'::text,'brieten'::text,'braten'::text,'brät'::text,'Gestern brieten sie die Rippchen über heißer Glut.'::text),
(313423,34825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вони ... ребра на гарячому вугіллі.'::text,'спекли'::text,'печуть'::text,'пече'::text,'Учора вони спекли ребра на гарячому вугіллі.'::text),
(313422,34825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ... las costillas sobre brasas.'::text,'asaron'::text,'asan'::text,'asa'::text,'Ayer asaron las costillas sobre brasas.'::text),
(313421,34825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, ils ... les côtes sur des braises.'::text,'ont rôti'::text,'rôtissent'::text,'rôtit'::text,'Hier, ils ont rôti les côtes sur des braises.'::text),
(313424,34825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün kaburgaları kor ateşin üstünde ...'::text,'kızarttılar'::text,'kızartırlar'::text,'kızartır'::text,'Dün kaburgaları kor ateşin üstünde kızarttılar.'::text),
(313425,34825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap forró parázs fölött ... a bordát.'::text,'sütötték'::text,'sütik'::text,'süti'::text,'Tegnap forró parázs fölött sütötték a bordát.'::text),
(313437,34827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Rippchen ... gerade auf dem heißen Stein, ohne Witz.'::text,'brutzeln'::text,'brutzeln'::text,'brutzeln'::text,'Bro, die Rippchen brutzeln gerade auf dem heißen Stein, ohne Witz.'::text),
(313441,34827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ребра саме зараз ... на гарячому камені, чесно.'::text,'печуться'::text,'печуться'::text,'печуться'::text,'Бро, ребра саме зараз печуться на гарячому камені, чесно.'::text),
(313440,34827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, las costillas ... en la piedra caliente ahora mismo, sin mentir.'::text,'se están asando'::text,'se asan'::text,'se están asando'::text,'Tío, las costillas se están asando en la piedra caliente ahora mismo, sin mentir.'::text),
(313439,34827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, les côtes ... sur la pierre chaude en ce moment, sans mentir.'::text,'sont en train de rôtir'::text,'rôtissent'::text,'sont en train de rôtir'::text,'Frère, les côtes sont en train de rôtir sur la pierre chaude en ce moment, sans mentir.'::text),
(313442,34827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaburgalar şu an sıcak taşta ..., cidden.'::text,'kızarıyor'::text,'kızarır'::text,'kızarıyor'::text,'Kanka, kaburgalar şu an sıcak taşta kızarıyor, cidden.'::text),
(313443,34827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a bordák most épp ... a forró kövön, komolyan.'::text,'sülnek'::text,'sülnek'::text,'sülnek'::text,'Tesó, a bordák most épp sülnek a forró kövön, komolyan.'::text),
(313446,34828,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Update: Normalerweise nutzen sie 1 Ofen, aber heute ... sie Rippchen auf einem Stein.'::text,'braten'::text,'braten'::text,NULL::text,'Update: Normalerweise nutzen sie 1 Ofen, aber heute braten sie Rippchen auf einem Stein.'::text),
(313450,34828,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення: зазвичай вони користуються 1 духовкою, але сьогодні ... ребра на камені.'::text,'печуть'::text,'печуть'::text,NULL::text,'Оновлення: зазвичай вони користуються 1 духовкою, але сьогодні печуть ребра на камені.'::text),
(313449,34828,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización: normalmente usan 1 horno, pero hoy ... costillas en una piedra.'::text,'están asando'::text,'asan'::text,NULL::text,'Actualización: normalmente usan 1 horno, pero hoy están asando costillas en una piedra.'::text),
(313448,34828,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mise à jour : d''habitude, ils utilisent 1 four, mais aujourd''hui ils ... des côtes sur une pierre.'::text,'sont en train de rôtir'::text,'rôtissent'::text,NULL::text,'Mise à jour : d''habitude, ils utilisent 1 four, mais aujourd''hui ils sont en train de rôtir des côtes sur une pierre.'::text),
(313451,34828,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güncelleme: genelde 1 fırın kullanırlar ama bugün kaburgaları taşta ...'::text,'kızartıyorlar'::text,'kızartırlar'::text,NULL::text,'Güncelleme: genelde 1 fırın kullanırlar ama bugün kaburgaları taşta kızartıyorlar.'::text),
(313452,34828,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frissítés: általában 1 sütőt használnak, de ma kövön ... a bordát.'::text,'sütik'::text,'sütik'::text,NULL::text,'Frissítés: általában 1 sütőt használnak, de ma kövön sütik a bordát.'::text),
(313455,34829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie braten die Rippchen draußen, ... das Zelt zum Sitzen ist.'::text,'weil'::text,'aber'::text,'also'::text,'Sie braten die Rippchen draußen, weil das Zelt zum Sitzen ist.'::text),
(313459,34829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони печуть ребра надворі, ... намет — для сидіння.'::text,'бо'::text,'але'::text,'тому'::text,'Вони печуть ребра надворі, бо намет — для сидіння.'::text),
(313458,34829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asan las costillas fuera ... la tienda es para sentarse.'::text,'porque'::text,'pero'::text,'así que'::text,'Asan las costillas fuera porque la tienda es para sentarse.'::text),
(313457,34829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils rôtissent les côtes dehors ... la tente, c''est pour s''asseoir.'::text,'parce que'::text,'mais'::text,'donc'::text,'Ils rôtissent les côtes dehors parce que la tente, c''est pour s''asseoir.'::text),
(313460,34829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaburgaları dışarıda kızartıyorlar ... çadır oturmak için.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Kaburgaları dışarıda kızartıyorlar çünkü çadır oturmak için.'::text),
(313461,34829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kint sütik a bordát, ... a sátor ülésre való.'::text,'mert'::text,'de'::text,'ezért'::text,'Kint sütik a bordát, mert a sátor ülésre való.'::text),
(308334,34260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rote Katze ... zwischen den Stäben des Absperrgitters durchschlüpfen.'::text,'kann'::text,'kann'::text,'kann'::text,'Die rote Katze kann zwischen den Stäben des Absperrgitters durchschlüpfen.'::text),
(308338,34260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руда кішка ... пролізти між прутами загородки.'::text,'може'::text,'може'::text,'може'::text,'Руда кішка може пролізти між прутами загородки.'::text),
(308337,34260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gata pelirroja ... pasar entre los barrotes de la puerta.'::text,'puede'::text,'puede'::text,'puede'::text,'La gata pelirroja puede pasar entre los barrotes de la puerta.'::text),
(308336,34260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat roux ... passer entre les barreaux de la porte.'::text,'peut'::text,'peut'::text,'peut'::text,'Le chat roux peut passer entre les barreaux de la porte.'::text),
(308339,34260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarman kedi kapının parmaklıklarının arasından ...'::text,'geçebilir'::text,'geçebilir'::text,'geçebilir'::text,'Sarman kedi kapının parmaklıklarının arasından geçebilir.'::text),
(308340,34260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vörös macska át ... bújni a kapu rácsai között.'::text,'tud'::text,'tud'::text,'tud'::text,'A vörös macska át tud bújni a kapu rácsai között.'::text),
(308352,34262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolles Gitter, echt jetzt. Gestern ... die Katze direkt zwischen seinen Stäben durch.'::text,'schlüpfte'::text,'schlüpft'::text,'schlüpfen'::text,'Tolles Gitter, echt jetzt. Gestern schlüpfte die Katze direkt zwischen seinen Stäben durch.'::text),
(308356,34262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова загородка, звісно. Учора кішка ... просто між її прутами.'::text,'пройшла'::text,'проходить'::text,'проходити'::text,'Чудова загородка, звісно. Учора кішка пройшла просто між її прутами.'::text),
(308355,34262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué gran puerta, obviamente. Ayer la gata ... justo entre sus barrotes.'::text,'pasó'::text,'pasa'::text,'pasar'::text,'Qué gran puerta, obviamente. Ayer la gata pasó justo entre sus barrotes.'::text),
(308354,34262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super porte, évidemment. Hier, le chat ... pile entre ses barreaux.'::text,'est passé'::text,'passe'::text,'passer'::text,'Super porte, évidemment. Hier, le chat est passé pile entre ses barreaux.'::text),
(308357,34262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika kapı, tabii. Dün kedi tam parmaklıklarının arasından ...'::text,'geçti'::text,'geçer'::text,'geçmek'::text,'Harika kapı, tabii. Dün kedi tam parmaklıklarının arasından geçti.'::text),
