(327049,36339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колодязь — це ... кругла яма, повна темної води.'::text,''::text,NULL::text,NULL::text,'Колодязь — це кругла яма, повна темної води.'::text),
(327048,36339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pozo es ... agujero redondo lleno de agua oscura.'::text,'un'::text,'el'::text,'un'::text,'Un pozo es un agujero redondo lleno de agua oscura.'::text),
(327047,36339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un puits est ... trou rond rempli d''eau sombre.'::text,'un'::text,'le'::text,'un'::text,'Un puits est un trou rond rempli d''eau sombre.'::text),
(327050,36339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuyu, karanlık suyla dolu yuvarlak ... çukurdur.'::text,'bir'::text,NULL::text,'bir'::text,'Kuyu, karanlık suyla dolu yuvarlak bir çukurdur.'::text),
(327051,36339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kút ... kerek, sötét vízzel teli lyuk.'::text,'egy'::text,'a'::text,'egy'::text,'A kút egy kerek, sötét vízzel teli lyuk.'::text),
(327054,36340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Brunnen ist rund, weil er ein runder Brunnen ist.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Brunnen ist rund, weil er ein runder Brunnen ist.'::text),
(327058,36340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... колодязь круглий, бо це круглий колодязь.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей колодязь круглий, бо це круглий колодязь.'::text),
(327057,36340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pozo es redondo porque es un pozo redondo.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este pozo es redondo porque es un pozo redondo.'::text),
(327056,36340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... puits est rond parce que c''est un puits rond.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce puits est rond parce que c''est un puits rond.'::text),
(327059,36340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kuyu yuvarlak çünkü yuvarlak bir kuyu.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu kuyu yuvarlak çünkü yuvarlak bir kuyu.'::text),
(327060,36340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kút kerek, mert ez egy kerek kút.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a kút kerek, mert ez egy kerek kút.'::text),
(327072,36342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Total verrückt! Die Jungs springen ... den Brunnen!'::text,'in'::text,'an'::text,'auf'::text,'Total verrückt! Die Jungs springen in den Brunnen!'::text),
(327076,36342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто шалено! Хлопці стрибають ... колодязь!'::text,'у'::text,'біля'::text,'на'::text,'Просто шалено! Хлопці стрибають у колодязь!'::text),
(327075,36342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una locura total! ¡Los chicos saltan ... pozo!'::text,'al'::text,'al'::text,'sobre el'::text,'¡Una locura total! ¡Los chicos saltan al pozo!'::text),
(327074,36342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Complètement fou ! Les garçons sautent ... puits !'::text,'dans le'::text,'au'::text,'sur le'::text,'Complètement fou ! Les garçons sautent dans le puits !'::text),
(327077,36342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen çılgınlık! Çocuklar kuyunun ... atlıyor!'::text,'içine'::text,NULL::text,'üstüne'::text,'Resmen çılgınlık! Çocuklar kuyunun içine atlıyor!'::text),
(327078,36342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totál őrület! A fiúk a ... ugrálnak!'::text,'kútba'::text,'kútnál'::text,'kúton'::text,'Totál őrület! A fiúk a kútba ugrálnak!'::text),
(327081,36343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut unglaublich! ... Jungs treiben im Brunnen wie ein Stern!'::text,'Fünf'::text,'Fünfte'::text,'Fünfen'::text,'Absolut unglaublich! Fünf Jungs treiben im Brunnen wie ein Stern!'::text),
(327085,36343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто неймовірно! ... хлопців пливуть у колодязі, як зірка!'::text,'П''ять'::text,'П''ятий'::text,'П''ятірки'::text,'Просто неймовірно! П''ять хлопців пливуть у колодязі, як зірка!'::text),
(327084,36343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente increíble! ¡... chicos flotan en el pozo como una estrella!'::text,'Cinco'::text,'Quinto'::text,'Cinco'::text,'¡Absolutamente increíble! ¡Cinco chicos flotan en el pozo como una estrella!'::text),
(327083,36343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument incroyable ! ... garçons flottent dans le puits comme une étoile !'::text,'Cinq'::text,'Cinquième'::text,'Cinq'::text,'Absolument incroyable ! Cinq garçons flottent dans le puits comme une étoile !'::text),
(327086,36343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! ... çocuk kuyuda yıldız gibi süzülüyor!'::text,'Beş'::text,'Beşinci'::text,'Beşler'::text,'İnanılmaz! Beş çocuk kuyuda yıldız gibi süzülüyor!'::text),
(327087,36343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút hihetetlen! ... fiú lebeg a kútban, mint egy csillag!'::text,'Öt'::text,'Ötödik'::text,'Ötösök'::text,'Abszolút hihetetlen! Öt fiú lebeg a kútban, mint egy csillag!'::text),
(301242,33472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er surft sonst auf dem Meer, aber gestern ... er in einem Indoor-Pool.'::text,'surfte'::text,'surft'::text,NULL::text,'Er surft sonst auf dem Meer, aber gestern surfte er in einem Indoor-Pool.'::text),
(301246,33472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він серфить у морі, але вчора ... у критому басейні.'::text,'серфив'::text,'серфить'::text,NULL::text,'Зазвичай він серфить у морі, але вчора серфив у критому басейні.'::text),
(301245,33472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente surfea en el mar, pero ayer ... en una piscina cubierta.'::text,'surfeó'::text,'surfea'::text,NULL::text,'Normalmente surfea en el mar, pero ayer surfeó en una piscina cubierta.'::text),
(301244,33472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, il surfe sur la mer, mais hier il ... dans une piscine couverte.'::text,'a surfé'::text,'surfe'::text,NULL::text,'D''habitude, il surfe sur la mer, mais hier il a surfé dans une piscine couverte.'::text),
(301247,33472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde denizde sörf yapar ama dün kapalı bir havuzda ...'::text,'sörf yaptı'::text,'sörf yapar'::text,NULL::text,'Genelde denizde sörf yapar ama dün kapalı bir havuzda sörf yaptı.'::text),
(301248,33472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában a tengeren szörfözik, de tegnap egy fedett medencében ...'::text,'szörfözött'::text,'szörfözik'::text,NULL::text,'Általában a tengeren szörfözik, de tegnap egy fedett medencében szörfözött.'::text),
(301260,33474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du surfst sonst draußen, aber heute ... du eine Indoor-Welle. Respekt.'::text,'reitest'::text,'reitest'::text,NULL::text,'Du surfst sonst draußen, aber heute reitest du eine Indoor-Welle. Respekt.'::text),
(301264,33474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти серфиш надворі, але сьогодні ... на хвилі в приміщенні. Респект.'::text,'катаєшся'::text,'катаєшся'::text,NULL::text,'Зазвичай ти серфиш надворі, але сьогодні катаєшся на хвилі в приміщенні. Респект.'::text),
(301263,33474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente surfeas al aire libre, pero hoy ... una ola en interior. Respeto.'::text,'estás cogiendo'::text,'coges'::text,NULL::text,'Normalmente surfeas al aire libre, pero hoy estás cogiendo una ola en interior. Respeto.'::text),
(301262,33474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, tu surfes dehors, mais aujourd''hui tu ... une vague en intérieur. Respect.'::text,'es en train de surfer'::text,'surfes'::text,NULL::text,'D''habitude, tu surfes dehors, mais aujourd''hui tu es en train de surfer une vague en intérieur. Respect.'::text),
(301265,33474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde dışarıda sörf yaparsın ama bugün kapalı alanda bir dalgada ... Saygı.'::text,'kayıyorsun'::text,'kayarsın'::text,NULL::text,'Genelde dışarıda sörf yaparsın ama bugün kapalı alanda bir dalgada kayıyorsun Saygı.'::text),
(301266,33474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában kint szörfözöl, de ma egy beltéri hullámon ... Respekt.'::text,'siklasz'::text,'siklasz'::text,NULL::text,'Általában kint szörfözöl, de ma egy beltéri hullámon siklasz Respekt.'::text),
(301269,33475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt ein genialer Move: Ich glaube, die Indoor-Welle ... ihn in Schaum hüllen.'::text,'wird'::text,'hüllte'::text,'hüllend'::text,'Echt ein genialer Move: Ich glaube, die Indoor-Welle wird ihn in Schaum hüllen.'::text),
(301273,33475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно геніальний хід: думаю, хвиля в приміщенні ... його піною.'::text,'накриє'::text,'накрила'::text,'накриваючи'::text,'Явно геніальний хід: думаю, хвиля в приміщенні накриє його піною.'::text),
(301272,33475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una jugada genial: creo que la ola interior lo ... de espuma.'::text,'cubrirá'::text,'cubrió'::text,'cubriendo'::text,'Claramente una jugada genial: creo que la ola interior lo cubrirá de espuma.'::text),
(301271,33475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un coup de génie : je pense que la vague intérieure le ... d''écume.'::text,'couvrira'::text,'a couvert'::text,'couvrant'::text,'Clairement un coup de génie : je pense que la vague intérieure le couvrira d''écume.'::text),
(301274,33475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen dahice bir hamle: bence kapalı alandaki dalga onu köpüğe ...'::text,'boğacak'::text,'boğdu'::text,'boğarak'::text,'Resmen dahice bir hamle: bence kapalı alandaki dalga onu köpüğe boğacak.'::text),
(301275,33475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván zseniális húzás: szerintem a beltéri hullám habba ... őt.'::text,'fogja borítani'::text,'borította'::text,'borítva'::text,'Nyilván zseniális húzás: szerintem a beltéri hullám habba fogja borítani őt.'::text),
(301278,33476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makelloser Ritt, klar. Jene Indoor-Welle ... ihn unter den Schaum ziehen.'::text,'wird'::text,'wird'::text,'zieht'::text,'Makelloser Ritt, klar. Jene Indoor-Welle wird ihn unter den Schaum ziehen.'::text),
(301282,33476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний заїзд, звісно. Та хвиля в приміщенні ... його під піну.'::text,'збирається затягти'::text,'затягне'::text,'затягує'::text,'Бездоганний заїзд, звісно. Та хвиля в приміщенні збирається затягти його під піну.'::text),
(301281,33476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un paseo impecable, obviamente. Esa ola interior lo ... bajo la espuma.'::text,'va a arrastrar'::text,'arrastrará'::text,'arrastra'::text,'Un paseo impecable, obviamente. Esa ola interior lo va a arrastrar bajo la espuma.'::text),
(301280,33476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ride parfait, évidemment. Cette vague intérieure ... sous l''écume.'::text,'va l''entraîner'::text,'l''entraînera'::text,'l''entraîne'::text,'Ride parfait, évidemment. Cette vague intérieure va l''entraîner sous l''écume.'::text),
(301283,33476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz sürüş, tabii. O kapalı alan dalgası onu köpüğün altına ...'::text,'çekecek'::text,'çekecek'::text,'çeker'::text,'Kusursuz sürüş, tabii. O kapalı alan dalgası onu köpüğün altına çekecek.'::text),
(301284,33476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan menet, nyilván. Az a beltéri hullám le ... húzni őt a hab alá.'::text,'fogja'::text,'fogja'::text,'húzza'::text,'Hibátlan menet, nyilván. Az a beltéri hullám le fogja húzni őt a hab alá.'::text),
(301287,33477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, diese Indoor-Welle ist viel ... als an meinem Strand, echt.'::text,'größer'::text,'größer'::text,'am größten'::text,'Bro, diese Indoor-Welle ist viel größer als an meinem Strand, echt.'::text),
(301291,33477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця хвиля в приміщенні набагато ..., ніж на моєму пляжі, чесно.'::text,'більша'::text,'більш велика'::text,'найбільша'::text,'Бро, ця хвиля в приміщенні набагато більша, ніж на моєму пляжі, чесно.'::text),
(301290,33477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esta ola interior es mucho ... que las de mi playa, en serio.'::text,'más grande'::text,'más grande'::text,'la más grande'::text,'Tío, esta ola interior es mucho más grande que las de mi playa, en serio.'::text),
(301289,33477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette vague intérieure est bien ... que sur ma plage, sérieux.'::text,'plus grande'::text,'plus grande'::text,'la plus grande'::text,'Frère, cette vague intérieure est bien plus grande que sur ma plage, sérieux.'::text),
(301292,33477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu kapalı alan dalgası benim sahildekinden çok ..., cidden.'::text,'daha büyük'::text,'daha büyük'::text,'en büyük'::text,'Kanka, bu kapalı alan dalgası benim sahildekinden çok daha büyük, cidden.'::text),
(301293,33477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a beltéri hullám sokkal ..., mint a helyi strandomon, komolyan.'::text,'nagyobb'::text,'nagyobb'::text,'legnagyobb'::text,'Tesó, ez a beltéri hullám sokkal nagyobb, mint a helyi strandomon, komolyan.'::text),
(301296,33478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Schaum bedeckt ihn ... in diesem Indoor-Pool, der ist erledigt.'::text,'komplett'::text,'komplett'::text,'Vollendung'::text,'Bro, der Schaum bedeckt ihn komplett in diesem Indoor-Pool, der ist erledigt.'::text),
(301300,33478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, піна ... накриває його в тому критому басейні, йому капець.'::text,'повністю'::text,'повний'::text,'завершення'::text,'Бро, піна повністю накриває його в тому критому басейні, йому капець.'::text),
(301299,33478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la espuma lo cubre ... en esa piscina cubierta, está acabado.'::text,'completamente'::text,'completo'::text,'finalización'::text,'Tío, la espuma lo cubre completamente en esa piscina cubierta, está acabado.'::text),
(301298,33478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''écume le recouvre ... dans cette piscine couverte, il est cuit.'::text,'complètement'::text,'complet'::text,'achèvement'::text,'Frère, l''écume le recouvre complètement dans cette piscine couverte, il est cuit.'::text),
(301301,33478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kapalı havuzda köpük onu ... kaplıyor, adam bitti.'::text,'tamamen'::text,'tam'::text,'tamamlanma'::text,'Kanka, o kapalı havuzda köpük onu tamamen kaplıyor, adam bitti.'::text),
(301302,33478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a hab ... beteríti abban a fedett medencében, ennek annyi.'::text,'teljesen'::text,'teljes'::text,'befejezés'::text,'Tesó, a hab teljesen beteríti abban a fedett medencében, ennek annyi.'::text),
(326406,36268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Zwei Mechaniker ... den schlammigen Fahrer mit einem Schlauch!'::text,'waschen'::text,'wäscht'::text,'waschend'::text,'Albtraum! Zwei Mechaniker waschen den schlammigen Fahrer mit einem Schlauch!'::text),
(326410,36268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Двоє механіків ... забрьоханого гонщика зі шланга!'::text,'миють'::text,'миє'::text,'миючи'::text,'Жах! Двоє механіків миють забрьоханого гонщика зі шланга!'::text),
(326409,36268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Dos mecánicos ... al piloto lleno de barro con una manguera!'::text,'lavan'::text,'lava'::text,'lavando'::text,'¡Pesadilla! ¡Dos mecánicos lavan al piloto lleno de barro con una manguera!'::text),
(326408,36268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Deux mécaniciens ... le pilote couvert de boue au jet !'::text,'lavent'::text,'lave'::text,'lavant'::text,'Cauchemar ! Deux mécaniciens lavent le pilote couvert de boue au jet !'::text),
(326411,36268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! İki tamirci çamurlu sürücüyü hortumla ...!'::text,'yıkarlar'::text,'yıkar'::text,'yıkayarak'::text,'Kâbus! İki tamirci çamurlu sürücüyü hortumla yıkarlar!'::text),
(326412,36268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Két szerelő slaggal ... a sáros versenyzőt!'::text,'mossák'::text,'mossa'::text,'mosva'::text,'Rémálom! Két szerelő slaggal mossák a sáros versenyzőt!'::text),
(326415,36269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut schrecklicher Schlamm! Nur ein Schlauch ... ihn abwaschen!'::text,'kann'::text,'ist'::text,'hat'::text,'Absolut schrecklicher Schlamm! Nur ein Schlauch kann ihn abwaschen!'::text),
(326419,36269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жахлива багнюка! Тільки шланг ... її змити!'::text,'може'::text,'є'::text,'має'::text,'Жахлива багнюка! Тільки шланг може її змити!'::text),
(326418,36269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Un barro horrible! ¡Solo una manguera ... quitarlo!'::text,'puede'::text,'está'::text,'tiene'::text,'¡Un barro horrible! ¡Solo una manguera puede quitarlo!'::text),
(326417,36269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une boue absolument horrible ! Seul un jet ... l''enlever !'::text,'peut'::text,'est'::text,'a'::text,'Une boue absolument horrible ! Seul un jet peut l''enlever !'::text),
(326420,36269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Berbat bir çamur! Onu ancak bir hortum ...!'::text,'temizleyebilir'::text,NULL::text,'var'::text,'Berbat bir çamur! Onu ancak bir hortum temizleyebilir!'::text),
(326421,36269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Borzalmas sár! Csak egy slag ... lemosni!'::text,'tudja'::text,'van'::text,'van'::text,'Borzalmas sár! Csak egy slag tudja lemosni!'::text),
(326424,36270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... waschen sie ihn? Mit einem Schlauch! Total brutal!'::text,'Womit'::text,'Wer'::text,'Wo'::text,'Womit waschen sie ihn? Mit einem Schlauch! Total brutal!'::text),
(326428,36270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... його миють? Шлангом! Просто жорстко!'::text,'Чим'::text,'Хто'::text,'Де'::text,'Чим його миють? Шлангом! Просто жорстко!'::text),
(326427,36270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Con ... lo lavan? ¡Con una manguera! ¡Brutal total!'::text,'qué'::text,'quién'::text,'dónde'::text,'¿Con qué lo lavan? ¡Con una manguera! ¡Brutal total!'::text),
(326426,36270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec ... est-ce qu''ils le lavent ? Au jet ! Complètement brutal !'::text,'quoi'::text,'qui'::text,'où'::text,'Avec quoi est-ce qu''ils le lavent ? Au jet ! Complètement brutal !'::text),
(326429,36270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu ... yıkıyorlar? Hortumla! Resmen acımasız!'::text,'neyle'::text,'kim'::text,'nerede'::text,'Onu neyle yıkıyorlar? Hortumla! Resmen acımasız!'::text),
(326430,36270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mossák le? Slaggal! Totál brutális!'::text,'Mivel'::text,'Ki'::text,'Hol'::text,'Mivel mossák le? Slaggal! Totál brutális!'::text),
(326433,36271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer ist voller Schlamm. Die Mechaniker ... ihn waschen.'::text,'werden'::text,'wird'::text,'werden'::text,'Der Fahrer ist voller Schlamm. Die Mechaniker werden ihn waschen.'::text),
(326437,36271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гонщик увесь у багнюці. Механіки ... його помити.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Гонщик увесь у багнюці. Механіки збираються його помити.'::text),
(326436,36271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto está lleno de barro. Los mecánicos ... lavarlo.'::text,'van a'::text,'va a'::text,'van a'::text,'El piloto está lleno de barro. Los mecánicos van a lavarlo.'::text),
(326435,36271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote est couvert de boue. Les mécaniciens ... le laver.'::text,'vont'::text,'va'::text,'vont'::text,'Le pilote est couvert de boue. Les mécaniciens vont le laver.'::text),
(326438,36271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürücü tamamen çamur içinde. Tamirciler onu ...'::text,'yıkayacak'::text,'yıkayacak'::text,'yıkayacak'::text,'Sürücü tamamen çamur içinde. Tamirciler onu yıkayacak.'::text),
(326439,36271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A versenyző csupa sár. A szerelők le ... mosni.'::text,'fogják'::text,'fogja'::text,'fogják'::text,'A versenyző csupa sár. A szerelők le fogják mosni.'::text),
(326442,36272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mechaniker hält den Schlauch, also ... er auch das Motorrad waschen.'::text,'wird'::text,'wird'::text,NULL::text,'Der Mechaniker hält den Schlauch, also wird er auch das Motorrad waschen.'::text),
(326446,36272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Механік тримає шланг, тож він ... помити й мотоцикл.'::text,'збирається'::text,'буде'::text,NULL::text,'Механік тримає шланг, тож він збирається помити й мотоцикл.'::text),
(326445,36272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mecánico sujeta la manguera, así que ... lavar la moto también.'::text,'va a'::text,NULL::text,NULL::text,'El mecánico sujeta la manguera, así que va a lavar la moto también.'::text),
(326444,36272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mécanicien tient le jet, donc il ... laver la moto aussi.'::text,'va'::text,NULL::text,NULL::text,'Le mécanicien tient le jet, donc il va laver la moto aussi.'::text),
(326447,36272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamirci hortumu tutuyor, bu yüzden motoru da ...'::text,'yıkayacak'::text,'yıkayacak'::text,NULL::text,'Tamirci hortumu tutuyor, bu yüzden motoru da yıkayacak.'::text),
(326448,36272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerelő fogja a slagot, ezért a motort is le ... mosni.'::text,'fogja'::text,'fogja'::text,NULL::text,'A szerelő fogja a slagot, ezért a motort is le fogja mosni.'::text),
(326451,36273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Teamregeln: Der Fahrer ... den Schlamm abwaschen, ohne Witz.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, Teamregeln: Der Fahrer muss den Schlamm abwaschen, ohne Witz.'::text),
(326455,36273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, правила команди: гонщик ... змити ту багнюку, чесно.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бро, правила команди: гонщик має змити ту багнюку, чесно.'::text),
(326454,36273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, normas del equipo: el piloto ... quitarse ese barro, sin mentir.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, normas del equipo: el piloto tiene que quitarse ese barro, sin mentir.'::text),
(326453,36273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, règles de l''équipe : le pilote ... enlever cette boue, sans mentir.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, règles de l''équipe : le pilote doit enlever cette boue, sans mentir.'::text),
(326456,36273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, takım kuralı: sürücü o çamuru ..., cidden.'::text,'yıkamak zorunda'::text,'yıkamalı'::text,'yıkamalı'::text,'Kanka, takım kuralı: sürücü o çamuru yıkamak zorunda, cidden.'::text),
(326457,36273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, csapatszabály: a versenyzőnek le ... mosnia azt a sarat, komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, csapatszabály: a versenyzőnek le kell mosnia azt a sarat, komolyan.'::text),
(326469,36275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie waschen den Fahrer, ... der Schlamm dreckig ist.'::text,'weil'::text,'aber'::text,'also'::text,'Sie waschen den Fahrer, weil der Schlamm dreckig ist.'::text),
(326473,36275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони миють гонщика, ... багнюка брудна.'::text,'бо'::text,'але'::text,'тому'::text,'Вони миють гонщика, бо багнюка брудна.'::text),
(326472,36275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lavan al piloto ... el barro está sucio.'::text,'porque'::text,'pero'::text,'así que'::text,'Lavan al piloto porque el barro está sucio.'::text),
(326471,36275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils lavent le pilote ... la boue est sale.'::text,'parce que'::text,'mais'::text,'donc'::text,'Ils lavent le pilote parce que la boue est sale.'::text),
(326474,36275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürücüyü yıkıyorlar ... çamur kirli.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Sürücüyü yıkıyorlar çünkü çamur kirli.'::text),
(326475,36275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megmossák a versenyzőt, ... a sár piszkos.'::text,'mert'::text,'de'::text,'ezért'::text,'Megmossák a versenyzőt, mert a sár piszkos.'::text),
(323004,35890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Panda ... die Schildkröte so fest, irgendwie süß.'::text,'hielt'::text,'hält'::text,'hielt'::text,'Bro, der Panda hielt die Schildkröte so fest, irgendwie süß.'::text),
(323008,35890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, панда ... черепашку так міцно, трохи мило.'::text,'тримала'::text,'тримає'::text,'тримала'::text,'Бро, панда тримала черепашку так міцно, трохи мило.'::text),
(323007,35890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el panda ... a la tortuga tan fuerte, en plan monísimo.'::text,'sujetó'::text,'sujeta'::text,'sujetó'::text,'Tío, el panda sujetó a la tortuga tan fuerte, en plan monísimo.'::text),
(323006,35890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le panda ... la tortue super serrée, un peu mignon.'::text,'a tenu'::text,'tient'::text,'a tenu'::text,'Frère, le panda a tenu la tortue super serrée, un peu mignon.'::text),
(323009,35890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, panda kaplumbağayı o kadar sıkı ..., bayağı tatlı.'::text,'tuttu'::text,'tutar'::text,'tuttu'::text,'Kanka, panda kaplumbağayı o kadar sıkı tuttu, bayağı tatlı.'::text),
(323010,35890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a panda olyan szorosan ... a teknőst, lowkey cuki.'::text,'fogta'::text,'fogja'::text,'fogta'::text,'Tesó, a panda olyan szorosan fogta a teknőst, lowkey cuki.'::text),
(323013,35891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Panda umarmt nie, aber gestern ... er die Schildkröte fest, echt.'::text,'umarmte'::text,'umarmt'::text,NULL::text,'Bro, der Panda umarmt nie, aber gestern umarmte er die Schildkröte fest, echt.'::text),
(323017,35891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, панда ніколи не обіймається, але вчора ... черепашку міцно, чесно.'::text,'обійняла'::text,'обіймає'::text,NULL::text,'Бро, панда ніколи не обіймається, але вчора обійняла черепашку міцно, чесно.'::text),
(323016,35891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el panda nunca abraza, pero ayer ... fuerte a la tortuga, en serio.'::text,'abrazó'::text,'abraza'::text,NULL::text,'Tío, el panda nunca abraza, pero ayer abrazó fuerte a la tortuga, en serio.'::text),
(323015,35891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le panda ne fait jamais de câlins, mais hier il ... fort la tortue dans ses bras, sérieux.'::text,'a serré'::text,'serre'::text,NULL::text,'Frère, le panda ne fait jamais de câlins, mais hier il a serré fort la tortue dans ses bras, sérieux.'::text),
(323018,35891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, panda asla sarılmaz ama dün kaplumbağaya sıkıca ..., cidden.'::text,'sarıldı'::text,'sarılır'::text,NULL::text,'Kanka, panda asla sarılmaz ama dün kaplumbağaya sıkıca sarıldı, cidden.'::text),
(323019,35891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a panda sosem ölelkezik, de tegnap szorosan ... a teknőst, komolyan.'::text,'megölelte'::text,'megöleli'::text,NULL::text,'Tesó, a panda sosem ölelkezik, de tegnap szorosan megölelte a teknőst, komolyan.'::text),
(323022,35892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Update um 15 Uhr: Der Panda ... die Schildkröte fest umarmt.'::text,'hält'::text,'hält'::text,'hält'::text,'Update um 15 Uhr: Der Panda hält die Schildkröte fest umarmt.'::text),
(323026,35892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення о 15:00: панда ... черепашку в міцних обіймах.'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Оновлення о 15:00: панда тримає черепашку в міцних обіймах.'::text),
(323025,35892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización a las 15:00: el panda ... a la tortuga en un abrazo fuerte.'::text,'está sujetando'::text,'sujeta'::text,'está sujetando'::text,'Actualización a las 15:00: el panda está sujetando a la tortuga en un abrazo fuerte.'::text),
(323024,35892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mise à jour à 15 h : le panda ... la tortue dans une étreinte serrée.'::text,'tient'::text,'tient'::text,'tient'::text,'Mise à jour à 15 h : le panda tient la tortue dans une étreinte serrée.'::text),
(323027,35892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 15.00 güncellemesi: panda kaplumbağayı sıkı bir kucaklamayla ...'::text,'tutuyor'::text,'tutar'::text,'tutuyor'::text,'Saat 15.00 güncellemesi: panda kaplumbağayı sıkı bir kucaklamayla tutuyor.'::text),
(323028,35892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frissítés 15 órakor: a panda szoros ölelésben ... a teknőst.'::text,'tartja'::text,'tartja'::text,'tartja'::text,'Frissítés 15 órakor: a panda szoros ölelésben tartja a teknőst.'::text),
(323031,35893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Die Schildkröte schwimmt sonst frei, aber jetzt ... der Panda sie fest!'::text,'drückt'::text,'drückt'::text,NULL::text,'Albtraum! Die Schildkröte schwimmt sonst frei, aber jetzt drückt der Panda sie fest!'::text),
(323035,35893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Черепашка зазвичай плаває вільно, але зараз панда її міцно ...!'::text,'стискає'::text,'стискає'::text,NULL::text,'Жах! Черепашка зазвичай плаває вільно, але зараз панда її міцно стискає!'::text),
(323034,35893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! La tortuga suele nadar libre, ¡pero ahora el panda la ... con fuerza!'::text,'está apretando'::text,'aprieta'::text,NULL::text,'¡Pesadilla! La tortuga suele nadar libre, ¡pero ahora el panda la está apretando con fuerza!'::text),
(323033,35893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! D''habitude, la tortue nage librement, mais là, le panda la ... fort !'::text,'est en train de serrer'::text,'serre'::text,NULL::text,'Cauchemar ! D''habitude, la tortue nage librement, mais là, le panda la est en train de serrer fort !'::text),
(323036,35893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Kaplumbağa genelde özgürce yüzer ama şimdi panda onu sıkı sıkı ...!'::text,'sıkıyor'::text,'sıkar'::text,NULL::text,'Kâbus! Kaplumbağa genelde özgürce yüzer ama şimdi panda onu sıkı sıkı sıkıyor!'::text),
(323037,35893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A teknős általában szabadon úszik, de most a panda szorosan ...!'::text,'szorongatja'::text,'szorongatja'::text,NULL::text,'Rémálom! A teknős általában szabadon úszik, de most a panda szorosan szorongatja!'::text),
(323049,35895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut erdrückend! Diese Umarmung ist ... als ein Sicherheitsgurt!'::text,'fester'::text,'fester'::text,'am festesten'::text,'Absolut erdrückend! Diese Umarmung ist fester als ein Sicherheitsgurt!'::text),
(323053,35895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто розчавлює! Ці обійми ..., ніж ремінь безпеки!'::text,'міцніші'::text,'більш міцні'::text,'найміцніші'::text,'Просто розчавлює! Ці обійми міцніші, ніж ремінь безпеки!'::text),
(323052,35895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente aplastante! ¡Este abrazo es ... que un cinturón de seguridad!'::text,'más apretado'::text,'más apretado'::text,'el más apretado'::text,'¡Absolutamente aplastante! ¡Este abrazo es más apretado que un cinturón de seguridad!'::text),
(323051,35895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument écrasant ! Ce câlin est ... qu''une ceinture de sécurité !'::text,'plus serré'::text,'plus serré'::text,'le plus serré'::text,'Absolument écrasant ! Ce câlin est plus serré qu''une ceinture de sécurité !'::text),
(323054,35895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen ezici! Bu sarılma emniyet kemerinden ...!'::text,'daha sıkı'::text,'daha sıkı'::text,'en sıkı'::text,'Resmen ezici! Bu sarılma emniyet kemerinden daha sıkı!'::text),
(323055,35895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totál fojtogató! Ez az ölelés ..., mint egy biztonsági öv!'::text,'szorosabb'::text,'szorosabb'::text,'legszorosabb'::text,'Totál fojtogató! Ez az ölelés szorosabb, mint egy biztonsági öv!'::text),
(323058,35896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Panda hält die Schildkröte ... in einer festen Umarmung.'::text,'vorsichtig'::text,'vorsichtig'::text,'Vorsicht'::text,'Der Panda hält die Schildkröte vorsichtig in einer festen Umarmung.'::text),
(323062,35896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Панда ... тримає черепашку в міцних обіймах.'::text,'обережно'::text,'обережний'::text,'обережність'::text,'Панда обережно тримає черепашку в міцних обіймах.'::text),
(323061,35896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El panda sujeta ... a la tortuga en un abrazo fuerte.'::text,'cuidadosamente'::text,'cuidadoso'::text,'cuidado'::text,'El panda sujeta cuidadosamente a la tortuga en un abrazo fuerte.'::text),
(323060,35896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le panda tient ... la tortue dans une étreinte serrée.'::text,'soigneusement'::text,'soigneux'::text,'soin'::text,'Le panda tient soigneusement la tortue dans une étreinte serrée.'::text),
(323063,35896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Panda kaplumbağayı sıkı bir kucaklamayla ... tutuyor.'::text,'dikkatlice'::text,'dikkatli'::text,'dikkat'::text,'Panda kaplumbağayı sıkı bir kucaklamayla dikkatlice tutuyor.'::text),
(323064,35896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A panda ... tartja a teknőst szoros ölelésben.'::text,'óvatosan'::text,'óvatos'::text,'óvatosság'::text,'A panda óvatosan tartja a teknőst szoros ölelésben.'::text),
(321132,35682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat gesagt, es ... für die Hunde die ganze Woche sonnig sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Hör zu, er hat gesagt, es wird für die Hunde die ganze Woche sonnig sein.'::text),
(321136,35682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав, що для псів ... сонячно весь тиждень.'::text,'буде'::text,'буде'::text,'буде'::text,'Слухай, він сказав, що для псів буде сонячно весь тиждень.'::text),
(321135,35682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que ... hacer sol toda la semana para los perros.'::text,'va a'::text,'va a'::text,'va a'::text,'Oye, dijo que va a hacer sol toda la semana para los perros.'::text),
(321134,35682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il a dit qu''il ... faire beau toute la semaine pour les chiens.'::text,'va'::text,'va'::text,'va'::text,'Écoute, il a dit qu''il va faire beau toute la semaine pour les chiens.'::text),
(321137,35682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, köpekler için bütün hafta havanın güneşli ... söyledi.'::text,'olacağını'::text,'olacağını'::text,'olacağını'::text,'Dinle, köpekler için bütün hafta havanın güneşli olacağını söyledi.'::text),
(321138,35682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a kutyáknak egész héten napos idő ... lenni.'::text,'fog'::text,'fog'::text,'fog'::text,'Figyelj, azt mondta, hogy a kutyáknak egész héten napos idő fog lenni.'::text),
(321141,35683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er meinte zu mir: „Oh, es ist sonnig! Ich ... den Pool füllen.“'::text,'werde'::text,'werde'::text,NULL::text,'Mädel, er meinte zu mir: „Oh, es ist sonnig! Ich werde den Pool füllen.“'::text),
