(293598,32622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, igazi rajongó vagy ... a labdával a mancsodban.'::text,'ezzel'::text,'ezekkel'::text,'azokkal'::text,'Őszintén, igazi rajongó vagy ezzel a labdával a mancsodban.'::text),
(293601,32623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann liegt hinter dem Fan, mit ... Beinen auf dem Sofa.'::text,'seinen'::text,'ihren'::text,'seinen'::text,'Der Mann liegt hinter dem Fan, mit seinen Beinen auf dem Sofa.'::text),
(293605,32623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік лежить за фанатом, поклавши ... ноги на диван.'::text,'свої'::text,'свої'::text,'свої'::text,'Чоловік лежить за фанатом, поклавши свої ноги на диван.'::text),
(293604,32623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre está tumbado detrás del fan con ... piernas en el sofá.'::text,'sus'::text,'sus'::text,'sus'::text,'El hombre está tumbado detrás del fan con sus piernas en el sofá.'::text),
(293603,32623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme est allongé derrière le fan, ... jambes sur le canapé.'::text,'ses'::text,'ses'::text,'ses'::text,'L''homme est allongé derrière le fan, ses jambes sur le canapé.'::text),
(293606,32623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, ... bacakları kanepede, hayranın arkasında uzanıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam, onun bacakları kanepede, hayranın arkasında uzanıyor.'::text),
(293607,32623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi a rajongó mögött fekszik, a ... a kanapén.'::text,'lába'::text,'lába'::text,'lába'::text,'A férfi a rajongó mögött fekszik, a lába a kanapén.'::text),
(293610,32624,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hundefan sitzt ... dem Sofa und schaut Fußball.'::text,'auf'::text,'an'::text,'unter'::text,'Der Hundefan sitzt auf dem Sofa und schaut Fußball.'::text),
(293614,32624,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес-фанат сидить ... дивані й дивиться футбол.'::text,'на'::text,'біля'::text,'під'::text,'Пес-фанат сидить на дивані й дивиться футбол.'::text),
(293613,32624,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro fan está sentado ... el sofá y ve fútbol.'::text,'en'::text,'a'::text,'debajo de'::text,'El perro fan está sentado en el sofá y ve fútbol.'::text),
(293612,32624,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien fan est assis ... le canapé et regarde le foot.'::text,'sur'::text,'à'::text,'sous'::text,'Le chien fan est assis sur le canapé et regarde le foot.'::text),
(293615,32624,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek hayran kanepenin ... oturup futbol izliyor.'::text,'üstünde'::text,NULL::text,'altında'::text,'Köpek hayran kanepenin üstünde oturup futbol izliyor.'::text),
(293616,32624,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyarajongó a ... ül, és focit néz.'::text,'kanapén'::text,'kanapénál'::text,'kanapé alatt'::text,'A kutyarajongó a kanapén ül, és focit néz.'::text),
(293619,32625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fan hat ... Ball in den Pfoten.'::text,'einen'::text,'ersten'::text,'einmal'::text,'Der Fan hat einen Ball in den Pfoten.'::text),
(293623,32625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У фаната в лапах ... м''яч.'::text,'один'::text,'перший'::text,'раз'::text,'У фаната в лапах один м''яч.'::text),
(293622,32625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El fan tiene ... balón en las patas.'::text,'un'::text,'primer'::text,'una vez'::text,'El fan tiene un balón en las patas.'::text),
(293621,32625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fan a ... ballon dans les pattes.'::text,'un'::text,'premier'::text,'une fois'::text,'Le fan a un ballon dans les pattes.'::text),
(293624,32625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayranın patilerinde ... top var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Hayranın patilerinde bir top var.'::text),
(293625,32625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rajongó mancsában ... labda van.'::text,'egy'::text,'első'::text,'egyszer'::text,'A rajongó mancsában egy labda van.'::text),
(293628,32626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q2-Bericht: Der Fan hat nicht viel ... für einen neuen Fußball.'::text,'Geld'::text,'Geld'::text,'Euro'::text,'Q2-Bericht: Der Fan hat nicht viel Geld für einen neuen Fußball.'::text),
(293632,32626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт за Q2: у фаната небагато ... на новий футбольний м''яч.'::text,'грошей'::text,'грошей'::text,'євро'::text,'Звіт за Q2: у фаната небагато грошей на новий футбольний м''яч.'::text),
(293631,32626,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe del T2: el fan no tiene mucho ... para un balón nuevo.'::text,'dinero'::text,'dinero'::text,'euros'::text,'Informe del T2: el fan no tiene mucho dinero para un balón nuevo.'::text),
(293630,32626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport du T2 : le fan n''a pas beaucoup ... pour un nouveau ballon.'::text,'d''argent'::text,'d''argent'::text,'d''euros'::text,'Rapport du T2 : le fan n''a pas beaucoup d''argent pour un nouveau ballon.'::text),
(293633,32626,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2. çeyrek raporu: hayranın yeni bir futbol topu için pek ... yok.'::text,'parası'::text,'paraları'::text,'eurosu'::text,'2. çeyrek raporu: hayranın yeni bir futbol topu için pek parası yok.'::text),
(293634,32626,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Q2-es jelentés: a rajongónak nincs sok ... egy új focilabdára.'::text,'pénze'::text,'pénze'::text,'eurója'::text,'Q2-es jelentés: a rajongónak nincs sok pénze egy új focilabdára.'::text),
(297039,33005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre großen Creolen ... golden.'::text,'sind'::text,'ist'::text,'bin'::text,'Ihre großen Creolen sind golden.'::text),
(297043,33005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її великі сережки-кільця ... золоті.'::text,'є'::text,'є'::text,'є'::text,'Її великі сережки-кільця є золоті.'::text),
(297042,33005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus grandes aros ... de oro.'::text,'son'::text,'es'::text,'soy'::text,'Sus grandes aros son de oro.'::text),
(297041,33005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses grandes créoles ... en or.'::text,'sont'::text,'est'::text,'suis'::text,'Ses grandes créoles sont en or.'::text),
(297044,33005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük halka küpeleri altın ...'::text,''::text,NULL::text,NULL::text,'Büyük halka küpeleri altın.'::text),
(297045,33005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy karikafülbevalói aranyból ...'::text,'vannak'::text,'van'::text,'vagyok'::text,'A nagy karikafülbevalói aranyból vannak.'::text),
(297057,33007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, der goldene Gürtel ist schon in deinen Händen. Du ... ihn tragen.'::text,'wirst'::text,'wirst'::text,NULL::text,'Ehrlich, der goldene Gürtel ist schon in deinen Händen. Du wirst ihn tragen.'::text),
(297061,33007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, золотий пояс уже в тебе в руках. Ти його ...'::text,'збираєшся вдягнути'::text,'вдягнеш'::text,NULL::text,'Чесно, золотий пояс уже в тебе в руках. Ти його збираєшся вдягнути.'::text),
(297060,33007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, el cinturón dorado ya está en tus manos. Te lo ...'::text,'vas a poner'::text,'pondrás'::text,NULL::text,'Sinceramente, el cinturón dorado ya está en tus manos. Te lo vas a poner.'::text),
(297059,33007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la ceinture dorée est déjà entre tes mains. Tu ...'::text,'vas la porter'::text,'la porteras'::text,NULL::text,'Franchement, la ceinture dorée est déjà entre tes mains. Tu vas la porter.'::text),
(297062,33007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, altın kemer zaten elinde. Onu ...'::text,'takacaksın'::text,'takacaksın'::text,NULL::text,'Açıkçası, altın kemer zaten elinde. Onu takacaksın.'::text),
(297063,33007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az arany öv már a kezedben van. Fel ... venni.'::text,'fogod'::text,'fogod'::text,NULL::text,'Őszintén, az arany öv már a kezedben van. Fel fogod venni.'::text),
(297066,33008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr dezent, klar: Jedes goldene Teil ist ... als das davor.'::text,'größer'::text,'größer'::text,'am größten'::text,'Sehr dezent, klar: Jedes goldene Teil ist größer als das davor.'::text),
(297070,33008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже скромно, звісно: кожна золота прикраса ..., ніж попередня.'::text,'більша'::text,'більш велика'::text,'найбільша'::text,'Дуже скромно, звісно: кожна золота прикраса більша, ніж попередня.'::text),
(297069,33008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy discreto, obviamente: cada pieza de oro es ... que la anterior.'::text,'más grande'::text,'más grande'::text,'la más grande'::text,'Muy discreto, obviamente: cada pieza de oro es más grande que la anterior.'::text),
(297068,33008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très discret, évidemment : chaque pièce en or est ... que la précédente.'::text,'plus grande'::text,'plus grande'::text,'la plus grande'::text,'Très discret, évidemment : chaque pièce en or est plus grande que la précédente.'::text),
(297071,33008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok ince bir dokunuş, tabii: her altın parça bir öncekinden ...'::text,'daha büyük'::text,'daha büyük'::text,'en büyük'::text,'Çok ince bir dokunuş, tabii: her altın parça bir öncekinden daha büyük.'::text),
(297072,33008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon visszafogott, nyilván: minden aranydarab ..., mint az előző.'::text,'nagyobb'::text,'nagyobb'::text,'legnagyobb'::text,'Nagyon visszafogott, nyilván: minden aranydarab nagyobb, mint az előző.'::text),
(297084,33010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos, klar. Sie ... nur noch einen goldenen Armreif dazunehmen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Makellos, klar. Sie sollte nur noch einen goldenen Armreif dazunehmen.'::text),
(297088,33010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно, звісно. Вона ... додати ще лише один золотий браслет.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Бездоганно, звісно. Вона мала б додати ще лише один золотий браслет.'::text),
(297087,33010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable, obviamente. Ella ... añadir solo una pulsera de oro más.'::text,'debería'::text,'debería'::text,'debería'::text,'Impecable, obviamente. Ella debería añadir solo una pulsera de oro más.'::text),
(297086,33010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable, évidemment. Elle ... ajouter juste un bracelet en or de plus.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Impeccable, évidemment. Elle devrait ajouter juste un bracelet en or de plus.'::text),
(297089,33010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz, tabii. Sadece bir altın bilezik daha ...'::text,'eklemeli'::text,'eklemeli'::text,'eklemeli'::text,'Kusursuz, tabii. Sadece bir altın bilezik daha eklemeli.'::text),
(297090,33010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan, nyilván. Még csak egy arany karperecet ... hozzátennie.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Hibátlan, nyilván. Még csak egy arany karperecet kellene hozzátennie.'::text),
(297093,33011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Sie legt sich die goldenen Armreifen um, und zwar ... Absolut zu viele!'::text,'schnell!'::text,'schnell!'::text,'Schnelligkeit!'::text,'Unglaublich! Sie legt sich die goldenen Armreifen um, und zwar schnell! Absolut zu viele!'::text),
(297097,33011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Вона вдягає золоті браслети ... Просто забагато!'::text,'швидко!'::text,'швидкий!'::text,'швидкість!'::text,'Неймовірно! Вона вдягає золоті браслети швидко! Просто забагато!'::text),
(297096,33011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡Se pone las pulseras de oro ... ¡Absolutamente demasiadas!'::text,'rápidamente!'::text,'rápido!'::text,'rapidez!'::text,'¡Increíble! ¡Se pone las pulseras de oro rápidamente ¡Absolutamente demasiadas!'::text),
(297095,33011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Elle met les bracelets en or ... Beaucoup trop !'::text,'rapidement !'::text,'rapide !'::text,'rapidité !'::text,'Incroyable ! Elle met les bracelets en or rapidement ! Beaucoup trop !'::text),
(297098,33011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Altın bilezikleri takıyor, hem de ... Resmen çok fazla!'::text,'hızlıca!'::text,'hızlı!'::text,'hızlılık!'::text,'İnanılmaz! Altın bilezikleri takıyor, hem de hızlıca! Resmen çok fazla!'::text),
(297099,33011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Felveszi az arany karpereceket, méghozzá ... Totál túl sok!'::text,'gyorsan!'::text,'gyors!'::text,'gyorsaság!'::text,'Hihetetlen! Felveszi az arany karpereceket, méghozzá gyorsan! Totál túl sok!'::text),
(297102,33012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Handgelenk ist komplett voll, ... sie jeden goldenen Armreif will! Katastrophe!'::text,'weil'::text,'aber'::text,'also'::text,'Ihr Handgelenk ist komplett voll, weil sie jeden goldenen Armreif will! Katastrophe!'::text),
(297106,33012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її зап''ясток повністю заповнений, ... вона хоче кожен золотий браслет! Катастрофа!'::text,'бо'::text,'але'::text,'тому'::text,'Її зап''ясток повністю заповнений, бо вона хоче кожен золотий браслет! Катастрофа!'::text),
(297105,33012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su muñeca está completamente llena ... quiere todas las pulseras de oro! ¡Desastre!'::text,'porque'::text,'pero'::text,'así que'::text,'¡Su muñeca está completamente llena porque quiere todas las pulseras de oro! ¡Desastre!'::text),
(297104,33012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son poignet est complètement plein ... elle veut chaque bracelet en or ! Catastrophe !'::text,'parce qu'''::text,'mais'::text,'donc'::text,'Son poignet est complètement plein parce qu'' elle veut chaque bracelet en or ! Catastrophe !'::text),
(297107,33012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bileği tamamen dolu ... her altın bileziği istiyor! Felaket!'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Bileği tamamen dolu çünkü her altın bileziği istiyor! Felaket!'::text),
(297108,33012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csuklója teljesen tele van, ... minden arany karperecet akar! Katasztrófa!'::text,'mert'::text,'de'::text,'ezért'::text,'A csuklója teljesen tele van, mert minden arany karperecet akar! Katasztrófa!'::text),
(322032,35782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf die Mitte der Zielscheibe.'::text,'zielt'::text,'zielen'::text,'zielend'::text,'Sie zielt auf die Mitte der Zielscheibe.'::text),
(322036,35782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... в центр мішені.'::text,'цілиться'::text,'цілитися'::text,'цілячись'::text,'Вона цілиться в центр мішені.'::text),
(322035,35782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... al centro de la diana.'::text,'apunta'::text,'apuntar'::text,'apuntando'::text,'Ella apunta al centro de la diana.'::text),
(322034,35782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le centre de la cible.'::text,'vise'::text,'viser'::text,'visant'::text,'Elle vise le centre de la cible.'::text),
(322037,35782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefin ortasına ...'::text,'nişan alır'::text,'nişan almak'::text,'nişan alarak'::text,'Hedefin ortasına nişan alır.'::text),
(322038,35782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A céltábla közepére ...'::text,'céloz'::text,'célozni'::text,'célzó'::text,'A céltábla közepére céloz.'::text),
(322041,35783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Zielscheibe aus großer Entfernung treffen.'::text,'kann'::text,'ist'::text,'hat'::text,'Sie kann die Zielscheibe aus großer Entfernung treffen.'::text),
(322045,35783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... влучити в мішень здалеку.'::text,'може'::text,'є'::text,'має'::text,'Вона може влучити в мішень здалеку.'::text),
(322044,35783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... dar en la diana desde muy lejos.'::text,'puede'::text,'está'::text,'tiene'::text,'Ella puede dar en la diana desde muy lejos.'::text),
(322043,35783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... toucher la cible de très loin.'::text,'peut'::text,'est'::text,'a'::text,'Elle peut toucher la cible de très loin.'::text),
(322046,35783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefi çok uzaktan ...'::text,'vurabilir'::text,NULL::text,'var'::text,'Hedefi çok uzaktan vurabilir.'::text),
(322047,35783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Messziről is el ... találni a céltáblát.'::text,'tudja'::text,'van'::text,'van'::text,'Messziről is el tudja találni a céltáblát.'::text),
(322050,35784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... stehen im Gras.'::text,'3 Zielscheiben'::text,'3 Zielscheibe'::text,'3 Zielscheiben'::text,'3 Zielscheiben stehen im Gras.'::text),
(322054,35784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... стоять у траві.'::text,'3 мішені'::text,'3 мішень'::text,'3 мішені'::text,'3 мішені стоять у траві.'::text),
(322053,35784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... están en la hierba.'::text,'3 dianas'::text,'3 diana'::text,'3 dianas'::text,'3 dianas están en la hierba.'::text),
(322052,35784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se dressent dans l''herbe.'::text,'3 cibles'::text,'3 cible'::text,'3 cibles'::text,'3 cibles se dressent dans l''herbe.'::text),
(322055,35784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çimenlerin içinde duruyor.'::text,'3 hedef'::text,'3 hedef'::text,'3 hedefler'::text,'3 hedef çimenlerin içinde duruyor.'::text),
(322056,35784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... áll a fűben.'::text,'3 céltábla'::text,'3 céltábla'::text,'3 céltábla'::text,'3 céltábla áll a fűben.'::text),
(322068,35786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf dem Schießplatz sind ... Zielscheiben.'::text,'drei'::text,'dritte'::text,'Dreien'::text,'Auf dem Schießplatz sind drei Zielscheiben.'::text),
(322072,35786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На стрільбищі є ... мішені.'::text,'три'::text,'треті'::text,'трійки'::text,'На стрільбищі є три мішені.'::text),
(322071,35786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el campo de tiro hay ... dianas.'::text,'tres'::text,'terceras'::text,'tres'::text,'En el campo de tiro hay tres dianas.'::text),
(322070,35786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a ... cibles sur le pas de tir.'::text,'trois'::text,'troisièmes'::text,'trois'::text,'Il y a trois cibles sur le pas de tir.'::text),
(322073,35786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atış alanında ... hedef var.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Atış alanında üç hedef var.'::text),
(322074,35786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lőtéren ... céltábla van.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'A lőtéren három céltábla van.'::text),
(322077,35787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos, klar: Sie braucht sehr wenig ..., um die Zielscheibe zu treffen.'::text,'Übung'::text,'Übung'::text,'eine Übung'::text,'Makellos, klar: Sie braucht sehr wenig Übung, um die Zielscheibe zu treffen.'::text),
(322081,35787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно, звісно: їй треба зовсім мало ..., щоб влучити в мішень.'::text,'практики'::text,'практик'::text,'практики'::text,'Бездоганно, звісно: їй треба зовсім мало практики, щоб влучити в мішень.'::text),
(322080,35787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable, obviamente: necesita muy poca ... para dar en la diana.'::text,'práctica'::text,'práctica'::text,'una práctica'::text,'Impecable, obviamente: necesita muy poca práctica para dar en la diana.'::text),
(322079,35787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable, évidemment : elle a besoin de très peu ... pour toucher la cible.'::text,'d''entraînement'::text,'d''entraînement'::text,'d''un entraînement'::text,'Impeccable, évidemment : elle a besoin de très peu d''entraînement pour toucher la cible.'::text),
(322082,35787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz, tabii: hedefi vurmak için çok az ... ihtiyacı var.'::text,'pratiğe'::text,'pratiklere'::text,'bir pratiğe'::text,'Kusursuz, tabii: hedefi vurmak için çok az pratiğe ihtiyacı var.'::text),
(322083,35787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan, nyilván: nagyon kevés ... kell ahhoz, hogy eltalálja a céltáblát.'::text,'gyakorlás'::text,'gyakorlás'::text,'egy gyakorlás'::text,'Hibátlan, nyilván: nagyon kevés gyakorlás kell ahhoz, hogy eltalálja a céltáblát.'::text),
(322086,35788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die trifft heute so ... Zielscheiben, ohne Witz.'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Bro, die trifft heute so viele Zielscheiben, ohne Witz.'::text),
(322090,35788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, сьогодні вона влучить у так ... мішеней, чесно.'::text,'багато'::text,'багато'::text,'багато'::text,'Бро, сьогодні вона влучить у так багато мішеней, чесно.'::text),
(322089,35788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, hoy va a acertar ... dianas, sin mentir.'::text,'muchas'::text,'mucha'::text,'un montón de'::text,'Tío, hoy va a acertar muchas dianas, sin mentir.'::text),
(322088,35788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle va toucher ... cibles aujourd''hui, sans mentir.'::text,'beaucoup de'::text,'beaucoup de'::text,'plein de'::text,'Frère, elle va toucher beaucoup de cibles aujourd''hui, sans mentir.'::text),
(322091,35788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bugün o kadar ... hedef vuracak ki, cidden.'::text,'çok'::text,'çok'::text,'çok'::text,'Kanka, bugün o kadar çok hedef vuracak ki, cidden.'::text),
(322092,35788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ma olyan ... céltáblát fog eltalálni, komolyan.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Tesó, ma olyan sok céltáblát fog eltalálni, komolyan.'::text),
(304383,33821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jet fliegt tief, aber du ... trotzdem lächeln. Respekt!'::text,'kannst'::text,'kannst'::text,'kannst'::text,'Der Jet fliegt tief, aber du kannst trotzdem lächeln. Respekt!'::text),
(304387,33821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак летить низько, але ти все одно ... усміхатися. Респект!'::text,'можеш'::text,'можеш'::text,'можеш'::text,'Літак летить низько, але ти все одно можеш усміхатися. Респект!'::text),
(304386,33821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión vuela bajo, pero tú aún ... sonreír. ¡Respeto!'::text,'puedes'::text,'puedes'::text,'puedes'::text,'El avión vuela bajo, pero tú aún puedes sonreír. ¡Respeto!'::text),
(304385,33821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion vole bas, mais tu ... encore sourire. Respect !'::text,'peux'::text,'peux'::text,'peux'::text,'L''avion vole bas, mais tu peux encore sourire. Respect !'::text),
(304388,33821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçak alçaktan uçuyor ama sen yine de ... Saygılar!'::text,'gülümseyebilirsin'::text,'gülümseyebilirsin'::text,'gülümseyebilirsin'::text,'Uçak alçaktan uçuyor ama sen yine de gülümseyebilirsin Saygılar!'::text),
(304389,33821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép alacsonyan repül, de te még mindig ... mosolyogni. Respekt!'::text,'tudsz'::text,'tudsz'::text,'tudsz'::text,'A gép alacsonyan repül, de te még mindig tudsz mosolyogni. Respekt!'::text),
(304392,33822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fliegt der große Jet so tief? Über dem Zaun.'::text,'Wo'::text,'Wer'::text,'Wann'::text,'Wo fliegt der große Jet so tief? Über dem Zaun.'::text),
(304396,33822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... великий літак летить так низько? Над парканом.'::text,'Де'::text,'Хто'::text,'Коли'::text,'Де великий літак летить так низько? Над парканом.'::text),
(304395,33822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... vuela tan bajo el avión grande? Sobre la valla.'::text,'Dónde'::text,'Quién'::text,'Cuándo'::text,'¿Dónde vuela tan bajo el avión grande? Sobre la valla.'::text),
(304394,33822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le gros avion vole-t-il si bas ? Au-dessus de la clôture.'::text,'Où'::text,'Qui'::text,'Quand'::text,'Où le gros avion vole-t-il si bas ? Au-dessus de la clôture.'::text),
(304397,33822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük uçak ... bu kadar alçaktan uçuyor? Çitin üstünde.'::text,'nerede'::text,'kim'::text,'ne zaman'::text,'Büyük uçak nerede bu kadar alçaktan uçuyor? Çitin üstünde.'::text),
(304398,33822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... repül ilyen alacsonyan a nagy gép? A kerítés fölött.'::text,'Hol'::text,'Ki'::text,'Mikor'::text,'Hol repül ilyen alacsonyan a nagy gép? A kerítés fölött.'::text),
(304410,33824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, Jets fliegen normalerweise hoch, aber gestern ... einer super tief, ohne Witz.'::text,'flog'::text,'fliegt'::text,NULL::text,'Bro, Jets fliegen normalerweise hoch, aber gestern flog einer super tief, ohne Witz.'::text),
(304414,33824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, літаки зазвичай літають високо, але вчора один ... супернизько, чесно.'::text,'пролетів'::text,'летить'::text,NULL::text,'Бро, літаки зазвичай літають високо, але вчора один пролетів супернизько, чесно.'::text),
(304413,33824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, los aviones suelen volar alto, pero ayer uno ... superbajo, sin mentir.'::text,'voló'::text,'vuela'::text,NULL::text,'Tío, los aviones suelen volar alto, pero ayer uno voló superbajo, sin mentir.'::text),
(304412,33824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, d''habitude les avions volent haut, mais hier l''un d''eux ... super bas, sans mentir.'::text,'a volé'::text,'vole'::text,NULL::text,'Frère, d''habitude les avions volent haut, mais hier l''un d''eux a volé super bas, sans mentir.'::text),
(304415,33824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, uçaklar genelde yüksekten uçar ama dün biri süper alçaktan ..., cidden.'::text,'uçtu'::text,'uçar'::text,NULL::text,'Kanka, uçaklar genelde yüksekten uçar ama dün biri süper alçaktan uçtu, cidden.'::text),
(304416,33824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a gépek általában magasan repülnek, de tegnap az egyik szuperalacsonyan ..., komolyan.'::text,'repült'::text,'repül'::text,NULL::text,'Tesó, a gépek általában magasan repülnek, de tegnap az egyik szuperalacsonyan repült, komolyan.'::text),
(304419,33825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Jumbo ... tief direkt über seinen Kopf, Bro.'::text,'fliegt'::text,'fliegt'::text,'fliegt'::text,'Yo, der Jumbo fliegt tief direkt über seinen Kopf, Bro.'::text),
(304423,33825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, джамбо ... низько просто над його головою, бро.'::text,'летить'::text,'летить'::text,'летить'::text,'Йо, джамбо летить низько просто над його головою, бро.'::text),
(304422,33825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, el jumbo ... bajo justo encima de su cabeza, tío.'::text,'está volando'::text,'vuela'::text,'está volando'::text,'Ey, el jumbo está volando bajo justo encima de su cabeza, tío.'::text),
(304421,33825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le jumbo ... bas juste au-dessus de sa tête, frère.'::text,'est en train de voler'::text,'vole'::text,'est en train de voler'::text,'Yo, le jumbo est en train de voler bas juste au-dessus de sa tête, frère.'::text),
(304424,33825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, jumbo jet tam kafasının üstünden alçaktan ..., kanka.'::text,'uçuyor'::text,'uçar'::text,'uçuyor'::text,'Hey, jumbo jet tam kafasının üstünden alçaktan uçuyor, kanka.'::text),
(304425,33825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, a jumbo alacsonyan ... közvetlenül a feje fölött, tesó.'::text,'repül'::text,'repül'::text,'repül'::text,'Hé, a jumbo alacsonyan repül közvetlenül a feje fölött, tesó.'::text),
(304428,33826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Der zweite Jet fliegt 20 Meter ... als der erste.'::text,'tiefer'::text,'tiefer'::text,'am tiefsten'::text,'Bericht: Der zweite Jet fliegt 20 Meter tiefer als der erste.'::text),
(304432,33826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: другий літак летить на 20 метрів ..., ніж перший.'::text,'нижче'::text,'більш низько'::text,'найнижче'::text,'Звіт: другий літак летить на 20 метрів нижче, ніж перший.'::text),
(304431,33826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: el segundo avión vuela 20 metros ... que el primero.'::text,'más bajo'::text,'más bajo'::text,'el más bajo'::text,'Informe: el segundo avión vuela 20 metros más bajo que el primero.'::text),
(304430,33826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : le deuxième avion vole 20 mètres ... que le premier.'::text,'plus bas'::text,'plus bas'::text,'le plus bas'::text,'Rapport : le deuxième avion vole 20 mètres plus bas que le premier.'::text),
(304433,33826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: ikinci uçak ilkinden 20 metre ... uçuyor.'::text,'daha alçaktan'::text,'daha alçaktan'::text,'en alçaktan'::text,'Rapor: ikinci uçak ilkinden 20 metre daha alçaktan uçuyor.'::text),
(304434,33826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: a második gép 20 méterrel ... repül, mint az első.'::text,'alacsonyabban'::text,'alacsonyabban'::text,'legalacsonyabban'::text,'Jelentés: a második gép 20 méterrel alacsonyabban repül, mint az első.'::text),
(304437,33827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jet fliegt tief, also duckt er sich ..., weil tief unten ist.'::text,'schnell'::text,'schnell'::text,'Schnelligkeit'::text,'Der Jet fliegt tief, also duckt er sich schnell, weil tief unten ist.'::text),
(304441,33827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак летить низько, тож він ... пригинається, бо низько — це внизу.'::text,'швидко'::text,'швидкий'::text,'швидкість'::text,'Літак летить низько, тож він швидко пригинається, бо низько — це внизу.'::text),
(304440,33827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión vuela bajo, así que se agacha ... porque bajo es abajo.'::text,'rápidamente'::text,'rápido'::text,'rapidez'::text,'El avión vuela bajo, así que se agacha rápidamente porque bajo es abajo.'::text),
(304439,33827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion vole bas, donc il se baisse ... parce que bas, c''est en bas.'::text,'rapidement'::text,'rapide'::text,'rapidité'::text,'L''avion vole bas, donc il se baisse rapidement parce que bas, c''est en bas.'::text),
(304442,33827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçak alçaktan uçuyor, bu yüzden ... eğiliyor çünkü alçak aşağı demek.'::text,'hızlıca'::text,'hızlı'::text,'hızlılık'::text,'Uçak alçaktan uçuyor, bu yüzden hızlıca eğiliyor çünkü alçak aşağı demek.'::text),
(304443,33827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép alacsonyan repül, ezért ... lebukik, mert az alacsony az lent van.'::text,'gyorsan'::text,'gyors'::text,'gyorsaság'::text,'A gép alacsonyan repül, ezért gyorsan lebukik, mert az alacsony az lent van.'::text),
(320079,35565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... schaut der Lehrer die Linie genau entlang? Um sie zu prüfen.'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum schaut der Lehrer die Linie genau entlang? Um sie zu prüfen.'::text),
(320083,35565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... учитель дивиться прямо вздовж лінії? Щоб перевірити її.'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому учитель дивиться прямо вздовж лінії? Щоб перевірити її.'::text),
(320082,35565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... mira el profesor recto a lo largo de la fila? Para comprobarla.'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué mira el profesor recto a lo largo de la fila? Para comprobarla.'::text),
(320081,35565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le prof regarde-t-il droit le long de la ligne ? Pour la vérifier.'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi le prof regarde-t-il droit le long de la ligne ? Pour la vérifier.'::text),
(320084,35565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğretmen ... sıra boyunca dümdüz bakıyor? Kontrol etmek için.'::text,'neden'::text,'kim'::text,'nerede'::text,'Öğretmen neden sıra boyunca dümdüz bakıyor? Kontrol etmek için.'::text),
(320085,35565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... néz a tanár egyenesen végig a soron? Hogy ellenőrizze.'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért néz a tanár egyenesen végig a soron? Hogy ellenőrizze.'::text),
(320088,35566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal! Der Lehrer hat gesagt, dass der Junge direkt an die Linie ...'::text,'trat'::text,'tritt'::text,'trat'::text,'Rate mal! Der Lehrer hat gesagt, dass der Junge direkt an die Linie trat.'::text),
(320092,35566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знаєш що? Учитель сказав, що хлопець ... прямо до лінії.'::text,'ступив'::text,'ступає'::text,'ступив'::text,'Знаєш що? Учитель сказав, що хлопець ступив прямо до лінії.'::text),
(320091,35566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? El profe dijo que el chico ... directo hasta la línea.'::text,'avanzó'::text,'avanza'::text,'avanzó'::text,'¿Sabes qué? El profe dijo que el chico avanzó directo hasta la línea.'::text),
(320090,35566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi ? Le prof a dit que le garçon ... tout droit jusqu''à la ligne.'::text,'s''est avancé'::text,'s''avance'::text,'s''est avancé'::text,'Devine quoi ? Le prof a dit que le garçon s''est avancé tout droit jusqu''à la ligne.'::text),
(320093,35566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu? Öğretmen dedi ki çocuk dümdüz çizgiye ...'::text,'adım attı'::text,'adım atar'::text,'adım attı'::text,'Bil bakalım ne oldu? Öğretmen dedi ki çocuk dümdüz çizgiye adım attı.'::text),
(320094,35566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld! A tanár azt mondta, hogy a fiú egyenesen a vonalhoz ...'::text,'lépett'::text,'lép'::text,'lépett'::text,'Képzeld! A tanár azt mondta, hogy a fiú egyenesen a vonalhoz lépett.'::text),
(320106,35568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, die spannendste Stunde überhaupt: Der Lehrer ... geradeaus die Linie entlang.'::text,'geht'::text,'geht'::text,'geht'::text,'Klar, die spannendste Stunde überhaupt: Der Lehrer geht geradeaus die Linie entlang.'::text),
(320110,35568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, найзахопливіший урок: учитель ... прямо вздовж лінії.'::text,'іде'::text,'іде'::text,'іде'::text,'Звісно, найзахопливіший урок: учитель іде прямо вздовж лінії.'::text),
(320109,35568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, la clase más emocionante: el profesor ... recto a lo largo de la fila.'::text,'está caminando'::text,'camina'::text,'está caminando'::text,'Obviamente, la clase más emocionante: el profesor está caminando recto a lo largo de la fila.'::text),
(320108,35568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, le cours le plus passionnant : le prof ... tout droit le long de la ligne.'::text,'est en train de marcher'::text,'marche'::text,'est en train de marcher'::text,'Évidemment, le cours le plus passionnant : le prof est en train de marcher tout droit le long de la ligne.'::text),
(320111,35568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki en heyecanlı ders: öğretmen sıra boyunca dümdüz ...'::text,'yürüyor'::text,'yürür'::text,'yürüyor'::text,'Tabii ki en heyecanlı ders: öğretmen sıra boyunca dümdüz yürüyor.'::text),
(320112,35568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván a legizgalmasabb óra: a tanár egyenesen ... végig a soron.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'Nyilván a legizgalmasabb óra: a tanár egyenesen sétál végig a soron.'::text),
(320115,35569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für eine gut trainierte Klasse, klar. Ihr rennt sonst, aber jetzt ... ihr gerade.'::text,'steht'::text,'steht'::text,NULL::text,'Was für eine gut trainierte Klasse, klar. Ihr rennt sonst, aber jetzt steht ihr gerade.'::text),
(320119,35569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Який вишколений клас, звісно. Зазвичай ви бігаєте, а зараз ... рівно.'::text,'стоїте'::text,'стоїте'::text,NULL::text,'Який вишколений клас, звісно. Зазвичай ви бігаєте, а зараз стоїте рівно.'::text),
(320118,35569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué clase tan bien entrenada, claramente. Normalmente corréis, pero ahora ... rectos.'::text,'estáis'::text,'estáis'::text,NULL::text,'Qué clase tan bien entrenada, claramente. Normalmente corréis, pero ahora estáis rectos.'::text),
(320117,35569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelle classe bien entraînée, clairement. D''habitude vous courez, mais là, vous ... bien droits.'::text,'vous tenez'::text,'vous tenez'::text,NULL::text,'Quelle classe bien entraînée, clairement. D''habitude vous courez, mais là, vous vous tenez bien droits.'::text),
(320120,35569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kadar iyi eğitilmiş bir sınıf, belli. Genelde koşarsınız ama şimdi dimdik ...'::text,'duruyorsunuz'::text,'durursunuz'::text,NULL::text,'Ne kadar iyi eğitilmiş bir sınıf, belli. Genelde koşarsınız ama şimdi dimdik duruyorsunuz.'::text),
(320121,35569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda jól képzett osztály, egyértelműen. Általában futkostok, de most egyenesen ...'::text,'álltok'::text,'álltok'::text,NULL::text,'Micsoda jól képzett osztály, egyértelműen. Általában futkostok, de most egyenesen álltok.'::text),
(320124,35570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Reihe ist ... als die Reihe hinten.'::text,'gerader'::text,'gerader'::text,'am geradesten'::text,'Diese Reihe ist gerader als die Reihe hinten.'::text),
(320128,35570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей ряд ..., ніж ряд позаду.'::text,'рівніший'::text,'більш рівний'::text,'найрівніший'::text,'Цей ряд рівніший, ніж ряд позаду.'::text),
(320127,35570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta fila está ... que la fila de atrás.'::text,'más recta'::text,'más recta'::text,'la más recta'::text,'Esta fila está más recta que la fila de atrás.'::text),
(320126,35570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette rangée est ... que la rangée du fond.'::text,'plus droite'::text,'plus droite'::text,'la plus droite'::text,'Cette rangée est plus droite que la rangée du fond.'::text),
(320129,35570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sıra arkadaki sıradan ...'::text,'daha düz'::text,'daha düz'::text,'en düz'::text,'Bu sıra arkadaki sıradan daha düz.'::text),
(320130,35570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a sor ..., mint a hátsó sor.'::text,'egyenesebb'::text,'egyenesebb'::text,'legegyenesebb'::text,'Ez a sor egyenesebb, mint a hátsó sor.'::text),
(320133,35571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jungs stehen gerade und warten ... auf den Lehrer.'::text,'leise'::text,'leise'::text,'Stille'::text,'Die Jungs stehen gerade und warten leise auf den Lehrer.'::text),
(320137,35571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопці стоять рівно й ... чекають на вчителя.'::text,'тихо'::text,'тихий'::text,'тиша'::text,'Хлопці стоять рівно й тихо чекають на вчителя.'::text),
(320136,35571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los chicos están rectos y esperan ... al profesor.'::text,'silenciosamente'::text,'silencioso'::text,'silencio'::text,'Los chicos están rectos y esperan silenciosamente al profesor.'::text),
(320135,35571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les garçons se tiennent droits et attendent ... le prof.'::text,'silencieusement'::text,'silencieux'::text,'silence'::text,'Les garçons se tiennent droits et attendent silencieusement le prof.'::text),
(320138,35571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuklar dimdik durup öğretmeni ... bekliyor.'::text,'sessizce'::text,'sessiz'::text,'sessizlik'::text,'Çocuklar dimdik durup öğretmeni sessizce bekliyor.'::text),
(320139,35571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiúk egyenesen állnak, és ... várják a tanárt.'::text,'csendesen'::text,'csendes'::text,'csendesség'::text,'A fiúk egyenesen állnak, és csendesen várják a tanárt.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
